/* header */
.top{position:fixed;top:env(safe-area-inset-top,0px);left:0;right:0;z-index:50;display:flex;align-items:center;justify-content:space-between;gap:12px;height:var(--head);padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px));transition:background .3s,color .3s}
.top.solid{background:rgba(13,34,48,.9);backdrop-filter:blur(8px)}
.logo{font-family:var(--f-display);font-weight:900;font-size:26px;letter-spacing:.04em;text-decoration:none;line-height:1}
