.cta{display:inline-flex;align-items:center;min-height:44px;padding:0 18px;border-radius:999px;background:var(--foam);color:var(--deep);font-weight:700;font-size:14px;text-decoration:none;white-space:nowrap;border:0;cursor:pointer}
