.menu li b{font-family:var(--f-display);font-weight:900;font-size:clamp(38px,min(5vw,7.2vh),68px);line-height:.95;letter-spacing:.01em;transition:color .2s,transform .3s cubic-bezier(.2,.8,.2,1)}
.menu li small{font-size:13px;color:var(--mist)}
