/* ===== HERO ===== */
.hero{position:relative;height:100vh;min-height:560px;overflow:hidden;background:radial-gradient(120% 80% at 50% 110%,rgba(255,255,255,.12),transparent 60%)}
.hero-word{position:absolute;left:0;right:0;top:50%;transform:translateY(-58%);text-align:center;font-family:var(--f-display);font-weight:900;font-size:clamp(96px,27vw,420px);line-height:.8;color:rgba(238,243,240,.13);white-space:nowrap;user-select:none;pointer-events:none}
.wall{position:absolute;left:0;right:0;top:calc(var(--head) + 24px);bottom:calc(150px + env(safe-area-inset-bottom,0px));display:flex;justify-content:center;align-items:flex-end;pointer-events:none}
.wall .bd{flex:0 0 auto;height:calc(var(--h) * 1%);margin:0 -.9vw;transform-origin:50% 100%;will-change:transform;pointer-events:auto}
