.wall .bd:hover img{transform:translateY(-18px)}
.wall::after{content:"";position:absolute;left:4%;right:4%;bottom:-6px;height:22px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.35),transparent);z-index:-1}
.hero-copy{position:absolute;left:var(--gut-l);right:var(--gut-r);bottom:calc(28px + env(safe-area-inset-bottom,0px));display:flex;align-items:flex-end;justify-content:space-between;gap:24px;flex-wrap:wrap}
.hero-copy h1 .h1k{display:block;font-size:clamp(12px,1.1vw,14px);font-weight:700;letter-spacing:.08em;color:var(--sun);margin-bottom:6px;text-shadow:0 1px 8px rgba(0,0,0,.35)}
.hero-copy h1{margin:6px 0 0;font-size:clamp(22px,3.2vw,38px);font-weight:900;line-height:1.35;text-wrap:balance;max-width:18em}
.scroll-cue{font-family:var(--f-mono);font-size:12px;letter-spacing:.14em;color:var(--mist);display:flex;align-items:center;gap:10px}
.scroll-cue i{display:block;width:1px;height:40px;background:var(--mist);transform-origin:top;animation:cue 1.8s ease-in-out infinite}
@keyframes cue{0%{transform:scaleY(0)}50%{transform:scaleY(1)}100%{transform:scaleY(0);transform-origin:bottom}}

/* ===== TYPE SELECTOR (horizontal carousel) ===== */
.types{--slide:min(24vw,270px);--ped:#3fb48f;position:relative;overflow:hidden;background:var(--tsbg,#1e4a44);transition:background-color .6s ease;padding-top:calc(var(--head) + 18px);padding-bottom:40px}
.ts-head{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
.ts-head h2{margin:0;font-family:var(--f-display);font-weight:900;font-size:clamp(28px,3.4vw,44px);line-height:1}
.ts-hint{font-family:var(--f-mono);font-size:12px;letter-spacing:.12em;color:var(--mist);display:flex;align-items:center;gap:10px}
.ts-hint i{display:block;width:44px;height:1px;background:currentColor;position:relative}
.ts-hint i::after{content:"";position:absolute;right:0;top:-3px;width:7px;height:7px;border-top:1px solid currentColor;border-right:1px solid currentColor;transform:rotate(45deg)}
.ts-word{position:absolute;left:0;right:0;top:calc(var(--head) + 90px);display:flex;justify-content:center;text-align:center;font-family:var(--f-display);font-weight:900;font-size:clamp(110px,21vw,340px);line-height:.85;white-space:nowrap;color:rgba(238,243,240,.07);-webkit-text-stroke:1.5px rgba(238,243,240,.28);pointer-events:none;user-select:none;z-index:0;transition:opacity .3s}
.ts-stage{position:relative;height:clamp(360px,60vh,640px);margin-top:10px;z-index:1}
.ts-ped{position:absolute;left:50%;bottom:3%;width:calc(var(--slide) * 1.15);height:54px;transform:translateX(-50%);pointer-events:none}
.ts-ped::before{content:"";position:absolute;inset:0;border-radius:50%;background:radial-gradient(closest-side,rgba(255,255,255,.28),rgba(255,255,255,.06) 70%,transparent);border:1px solid rgba(255,255,255,.35)}
.ts-ped::after{content:"";position:absolute;inset:-30px -10px;border-radius:50%;background:radial-gradient(closest-side,var(--ped),transparent);opacity:.55;filter:blur(14px);transition:background .5s}
.ts-track{position:absolute;inset:0;display:flex;align-items:flex-end;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;scrollbar-width:none;padding-inline:calc(50% - var(--slide) / 2);padding-bottom:calc(3% + 26px);cursor:grab;outline-offset:-4px}
.ts-track::-webkit-scrollbar{display:none}
.ts-track.drag{cursor:grabbing;scroll-snap-type:none}
/* the snap target never moves; only its inner wrapper is tilted and scaled, so snap points stay exactly centered */
.ts-slide{flex:0 0 var(--slide);height:100%;scroll-snap-align:center;scroll-snap-stop:always;border:0;background:none;padding:0;cursor:pointer;position:relative}
.ts-inner{display:flex;align-items:flex-end;justify-content:center;width:100%;height:100%;transform-origin:50% 100%;will-change:transform,opacity}
.ts-slide svg{height:100%;width:100%;overflow:visible;filter:drop-shadow(0 26px 20px rgba(0,0,0,.38));pointer-events:none}
.ts-arrow{position:absolute;top:44%;z-index:20;width:48px;height:48px;border-radius:50%;border:1px solid rgba(238,243,240,.4);background:rgba(13,34,48,.35);color:var(--foam);display:grid;place-items:center;cursor:pointer;backdrop-filter:blur(4px)}
.ts-arrow:hover{background:var(--foam);color:var(--deep)}
.ts-arrow svg{width:18px;height:18px}
.ts-prev{left:max(16px,env(safe-area-inset-left,0px))}
.ts-next{right:max(16px,env(safe-area-inset-right,0px))}
.ts-tabs{position:relative;z-index:2;display:flex;justify-content:center;gap:6px;flex-wrap:wrap;margin:6px 0 26px}
.ts-tabs button{min-height:40px;padding:0 14px;border-radius:999px;border:1px solid rgba(238,243,240,.3);background:none;color:var(--mist);font-family:var(--f-mono);font-size:12px;letter-spacing:.08em;cursor:pointer}
.ts-tabs button[aria-current="true"]{background:var(--foam);color:var(--deep);border-color:var(--foam)}
.ts-info{position:relative;z-index:2;max-width:1180px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:20px clamp(24px,4vw,56px);align-items:start}
.ts-info .jp{font-size:15px;color:var(--mist);font-weight:700}
.ts-info h3{margin:2px 0 10px;font-family:var(--f-display);font-weight:900;font-size:clamp(44px,5.4vw,80px);line-height:.88;letter-spacing:.01em}
.ts-info .len{font-family:var(--f-mono);font-size:14px;color:var(--sun);margin:0 0 10px}
.ts-info p{margin:0 0 12px;color:#dce6e8;font-size:15px}
.ts-info .note{font-size:14px;color:var(--sun)}
.meters{display:grid;gap:10px;margin:4px 0 16px}
.meter{display:grid;grid-template-columns:72px 1fr;align-items:center;gap:10px;font-size:12px}
.meter .lab{font-family:var(--f-mono);letter-spacing:.1em;color:var(--mist)}
.meter .bar{position:relative;display:grid;grid-template-columns:repeat(var(--n),1fr);gap:3px}
.meter .bar i{height:8px;border-radius:2px;background:rgba(238,243,240,.16)}
.meter .bar i.on{background:var(--foam)}
.meter .ticks{grid-column:2;display:flex;justify-content:space-between;font-size:10px;color:var(--mist);margin-top:-4px}
.facts{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:18px}
.facts span{font-family:var(--f-mono);font-size:12px;padding:5px 9px;border:1px solid rgba(238,243,240,.3);border-radius:6px}

/* ===== CONFIGURATOR ===== */
