.bc-in{position:relative;max-width:1240px;margin:0 auto;display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(20px,4vw,48px);align-items:end}
.bc-copy{padding-bottom:90px;position:relative;z-index:2}
.bc-in .eyebrow{color:#9fd0e4;display:flex;gap:10px;align-items:center}
.bc-in .eyebrow::before{content:"";width:28px;height:1px;background:currentColor}
.bc-in h2{margin:14px 0 20px;font-family:var(--f-body);font-weight:900;font-size:clamp(30px,3.9vw,58px);line-height:1.15;letter-spacing:-.02em}
.bc-in h2 span{display:block;white-space:nowrap}
.bc-in h2 .out{color:transparent;-webkit-text-stroke:1.5px var(--sun)}
.bc-in p{margin:0 0 22px;max-width:28em;color:#cfe0e6}
.bc-list{list-style:none;margin:0 0 30px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.bc-list li{font-family:var(--f-mono);font-size:11.5px;letter-spacing:.08em;padding:6px 10px;border:1px dashed rgba(159,208,228,.55);border-radius:4px;color:#cfe0e6}
.buildcta .btn.big{background:var(--sun);border-color:var(--sun);color:var(--deep)}
.buildcta .btn.big:hover{background:var(--foam);border-color:var(--foam)}
/* the fan deck: boards pinned at one rivet, opened like a paint-swatch fan */
.fan-deck{--open:1;--step:9.6deg;position:relative;height:clamp(420px,52vw,640px);min-width:0}
.fd-stage{position:absolute;left:50%;bottom:0;width:0;height:100%}
.fd-board{position:absolute;left:0;bottom:46px;height:calc(var(--s) * 84%);aspect-ratio:var(--ar);transform-origin:50% calc(100% - 2px);transform:translateX(-50%) rotate(calc(var(--i) * var(--step) * var(--open))) translateY(var(--lift,0px));border:0;padding:0;background:none;cursor:pointer;transition:transform .45s cubic-bezier(.2,.8,.2,1)}
.fd-board svg{width:100%;height:100%;overflow:visible;filter:drop-shadow(0 14px 12px rgba(0,0,0,.35));pointer-events:none}
.fd-board{pointer-events:none}
.fd-board svg > g > path:first-of-type{pointer-events:visiblePainted;cursor:pointer}
.fd-board:hover,.fd-board:focus-visible{--lift:-34px;z-index:30!important}
.fd-board:focus-visible{outline:none}
.fd-board:focus-visible svg{filter:drop-shadow(0 0 0 #fff) drop-shadow(0 14px 12px rgba(0,0,0,.35))}
.fd-rivet{position:absolute;left:0;bottom:40px;width:30px;height:30px;transform:translate(-50%,0);border-radius:50%;background:radial-gradient(circle at 35% 35%,#fff,#b9c7cc 45%,#5b6d75);box-shadow:0 4px 10px rgba(0,0,0,.4);z-index:40}
.fd-arc{position:absolute;left:50%;bottom:55px;transform:translate(-50%,50%);width:calc(var(--r) * 2);height:calc(var(--r) * 2);border-radius:50%;border:1px dashed rgba(159,208,228,.35);pointer-events:none;--r:min(46vw,560px)}
.fd-read{position:absolute;right:0;top:8px;font-family:var(--f-mono);font-size:12px;letter-spacing:.06em;color:#cfe0e6;text-align:right;line-height:1.6;z-index:41;min-height:3.2em}
.fd-read b{display:block;font-family:var(--f-display);font-weight:900;font-size:26px;letter-spacing:.02em;color:var(--foam)}
.fd-count{position:absolute;left:0;top:8px;font-family:var(--f-mono);font-size:12px;color:#9fd0e4;letter-spacing:.1em}
.btn.big{min-height:56px;padding:0 28px;font-size:16px}
.seg{display:inline-flex;background:#fff;border:1px solid var(--line);border-radius:999px;padding:3px}
.seg button{min-height:38px;padding:0 14px;border:0;border-radius:999px;background:none;color:var(--ink);font-family:var(--f-mono);font-size:12px;letter-spacing:.08em;cursor:pointer}
.seg button[aria-pressed="true"]{background:var(--ink);color:#fff}
.cf-canvas{position:relative;flex:1;min-height:0;display:grid;place-items:center;perspective:1600px}
.cf-flip{position:absolute;inset:0;transform-style:preserve-3d}
#cfSvg{position:absolute;left:0;top:2%;width:100%;height:94%;overflow:visible;filter:drop-shadow(0 28px 22px rgba(13,34,48,.28));touch-action:manipulation}
#cfSvg.picking{cursor:crosshair}
.floor{position:absolute;bottom:3%;left:50%;width:min(260px,40%);height:18px;transform:translateX(-50%);border-radius:50%;background:radial-gradient(closest-side,rgba(13,34,48,.25),transparent);pointer-events:none}
.cf-canvas canvas.three{position:absolute;left:0;top:0;width:100%;height:100%;display:block;touch-action:none;cursor:grab;z-index:1}
.cf-canvas canvas.three.dragging{cursor:grabbing}
.spray-fx{position:absolute;left:0;top:0;width:100%;height:100%;pointer-events:none;z-index:4}
.spray-fx.top{z-index:5}
.spray-sw .toggle small{display:block;font-size:11.5px;color:var(--ink-soft);font-weight:400;margin-left:26px;margin-top:-2px}
.cf-canvas.is3d .cf-flip{visibility:hidden}
.cf-canvas.is3d .floor{display:none}
.v3hint{position:absolute;left:50%;bottom:10px;transform:translateX(-50%);z-index:3;pointer-events:none;font-family:var(--f-mono);font-size:11px;letter-spacing:.06em;color:var(--ink-soft);background:rgba(255,255,255,.78);padding:4px 10px;border-radius:999px;white-space:nowrap}
.cf-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.ori-ic{width:14px;height:14px;margin-right:4px;vertical-align:-2px}
.cf-canvas.is-h .hc{display:none}
.hc{position:absolute;left:14px;bottom:10px;z-index:4;display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.hc-btn{display:inline-flex;align-items:center;gap:6px;min-height:40px;padding:0 14px 0 10px;border-radius:999px;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:12.5px;font-weight:700;cursor:pointer}
.hc-btn svg{width:18px;height:18px}
.hc-btn[aria-pressed="true"]{background:var(--ink);color:#fff;border-color:var(--ink)}
.hc-in{display:inline-flex;align-items:center;gap:6px;min-height:40px;padding:0 10px;border-radius:999px;background:#fff;border:1px solid var(--line);font-size:12.5px;color:var(--ink-soft)}
.hc-in input{width:64px;min-height:30px;border:0;border-bottom:1.5px solid var(--ink);background:none;color:var(--ink);font-family:var(--f-mono);font-size:15px;text-align:center}
.hc-in input:focus{outline:none;border-color:var(--sun)}
/* shaping animation */
.shapefx{position:absolute;inset:0;z-index:6;background:radial-gradient(60% 55% at 50% 52%,#ffffff 0%,var(--studio) 70%);pointer-events:none;opacity:1;transition:opacity .4s}
.shapefx.out{opacity:0}
.shapefx svg{position:absolute;left:0;top:2%;width:100%;height:94%;overflow:visible}
.shapefx canvas{position:absolute;inset:0;width:100%;height:100%}
.fx-hud{position:absolute;left:16px;top:12px;display:grid;gap:6px;font-family:var(--f-mono);font-size:11px;letter-spacing:.1em;color:var(--ink);min-width:170px}
.fx-hud .st{display:flex;justify-content:space-between;gap:12px}
.fx-hud i{display:block;height:3px;background:rgba(13,34,48,.12);border-radius:2px;overflow:hidden}
.fx-hud i b{display:block;height:100%;width:0;background:var(--ink)}
.fx-hud ol{list-style:none;margin:4px 0 0;padding:0;display:grid;gap:2px;color:rgba(13,34,48,.35)}
.fx-hud li.on{color:var(--ink)}
.fx-hud li.done{color:#1f6b4f}
.fx-skip{position:absolute;right:14px;top:12px;pointer-events:auto;min-height:36px;padding:0 14px;border-radius:999px;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:12px;font-weight:700;cursor:pointer}
.fx-done{position:absolute;left:50%;bottom:6%;transform:translateX(-50%);font-family:var(--f-display);font-weight:900;font-size:clamp(22px,3vw,34px);letter-spacing:.06em;color:var(--ink);opacity:0;white-space:nowrap}
/* hero water */
.ripple{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:0}
@media (max-width:860px){.cf-tools{gap:6px}.cf-tools .seg button{padding:0 10px}.hc{left:10px;bottom:6px}.v3hint{display:none}.fx-hud{left:10px;top:8px;min-width:140px}}
.tap-hint{pointer-events:none;position:absolute;top:12px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;font-size:13px;padding:6px 12px;border-radius:999px;white-space:nowrap}
.cf-read{display:flex;justify-content:center;gap:clamp(12px,3vw,36px);padding:8px 16px 18px;flex-wrap:wrap}
.cf-read div{text-align:center}
.cf-read b{display:block;font-family:var(--f-display);font-weight:900;font-size:clamp(24px,2.6vw,34px);line-height:1;font-variant-numeric:tabular-nums}
.cf-read span{font-family:var(--f-mono);font-size:10px;letter-spacing:.12em;color:var(--ink-soft)}

.cf-panel{background:#fff;border-left:1px solid var(--line);height:100%;overflow-y:auto;overscroll-behavior:contain;padding:calc(10px + env(safe-area-inset-top,0px)) env(safe-area-inset-right,0px) calc(40px + env(safe-area-inset-bottom,0px)) 0;display:flex;flex-direction:column;min-width:0}
.steps-nav{display:grid;grid-template-columns:repeat(5,1fr);margin:0 22px;border-bottom:1px solid var(--line);position:sticky;top:-10px;background:#fff;z-index:3}
.steps-nav button{min-height:52px;background:none;border:0;border-bottom:3px solid transparent;color:var(--ink-soft);cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;padding:4px 0}
.steps-nav button small{font-family:var(--f-mono);font-size:10px;letter-spacing:.08em}
.steps-nav button b{font-size:13px}
.steps-nav button[aria-current="step"]{color:var(--ink);border-bottom-color:var(--ink)}
.pane{padding:22px 22px 0;display:grid;gap:22px}
.pane h3{margin:0;font-family:var(--f-display);font-weight:900;font-size:40px;line-height:.95}
.pane .sub{margin:-14px 0 0;color:var(--ink-soft);font-size:14px}
.group{display:grid;gap:10px}
.group > .gl{display:flex;justify-content:space-between;align-items:baseline;gap:8px;font-family:var(--f-mono);font-size:11px;letter-spacing:.12em;color:var(--ink-soft);text-transform:uppercase}
.group > .gl output{font-size:14px;color:var(--ink);letter-spacing:0;text-transform:none;font-variant-numeric:tabular-nums}
.opts{display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:8px}
.opt{position:relative;text-align:left;border:1px solid var(--line);background:#fff;border-radius:10px;padding:10px 12px;min-height:56px;cursor:pointer;color:var(--ink);display:grid;gap:2px;align-content:start}
.opt b{font-size:14px}
.opt small{font-size:11.5px;line-height:1.5;color:var(--ink-soft)}
.opt[aria-pressed="true"]{border-color:var(--ink);box-shadow:inset 0 0 0 1.5px var(--ink);background:#f6f9f9}
.opt .mini{height:58px;width:100%;margin-bottom:4px}
.opts.types-o{grid-template-columns:repeat(5,1fr)}
.opts.types-o .opt{padding:8px 4px;text-align:center;justify-items:center}
.opts.types-o .opt b{font-size:12px}
.desc{margin:0;font-size:13.5px;color:var(--ink-soft);line-height:1.7}
.notice{border:1px solid #e6c98a;background:#fff9ea;border-radius:10px;padding:14px 16px;display:grid;gap:6px;color:var(--ink)}
.notice .nt{display:flex;align-items:center;gap:7px;font-size:13.5px;color:#7a5410}
.notice .nt svg{width:18px;height:18px;flex:none}
.notice p{margin:0;font-size:12.5px;line-height:1.75;color:#3a4a52;padding-left:1em;text-indent:-1em}
.order .notice{margin-top:22px;max-width:40em}
input[type=range]{width:100%;accent-color:var(--ink);height:28px}
.vol{background:var(--studio);border-radius:12px;padding:14px;display:grid;gap:10px}
.vol-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.vol label{display:grid;gap:4px;font-size:12px;color:var(--ink-soft)}
.vol input,.vol select{min-height:40px;border:1px solid var(--line);border-radius:8px;padding:0 10px;background:#fff;color:var(--ink)}
.vol-out{font-size:14px}
.vol-out b{font-variant-numeric:tabular-nums}
.chip{display:inline-block;font-size:12px;padding:2px 8px;border-radius:999px;background:var(--ink);color:#fff;margin-left:6px}
.chip.warn{background:#9b3a64}
.targets{display:flex;flex-wrap:wrap;gap:6px}
.targets button{min-height:40px;padding:0 12px;border:1px solid var(--line);border-radius:999px;background:#fff;color:var(--ink);cursor:pointer;display:inline-flex;align-items:center;gap:8px;font-size:13px}
.targets button i{width:16px;height:16px;border-radius:50%;border:1px solid rgba(0,0,0,.2)}
.targets button[aria-pressed="true"]{background:var(--ink);color:#fff}
.sw{display:grid;grid-template-columns:repeat(7,1fr);gap:8px}
.sw button{aspect-ratio:1;max-width:100%;border-radius:50%;border:1px solid rgba(0,0,0,.15);cursor:pointer;position:relative;min-height:36px}
.sw button[aria-pressed="true"]::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid var(--ink)}
.picker{display:flex;align-items:center;gap:10px;font-size:13px}
.picker input[type=color]{width:52px;height:40px;border:1px solid var(--line);border-radius:8px;padding:2px;background:#fff;cursor:pointer}
.picker code{font-family:var(--f-mono);font-size:13px}
.toggle{display:flex;align-items:center;gap:10px;font-size:14px;min-height:40px;cursor:pointer}
.toggle input{width:20px;height:20px;accent-color:var(--ink)}
.presets{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.presets .opt{justify-items:center;text-align:center}
.presets .opt .mini{height:70px}
.presets .opt b{font-size:12px}
.next{display:flex;justify-content:space-between;gap:10px;padding:6px 22px 0}
.btn{min-height:48px;padding:0 20px;border-radius:999px;border:1px solid var(--ink);background:var(--ink);color:#fff;font-weight:700;cursor:pointer;font-size:14px;display:inline-flex;align-items:center;justify-content:center;text-decoration:none}
.btn.ghost{background:#fff;color:var(--ink)}
.sheetcard{position:relative;overflow:hidden;border:1.5px solid var(--ink);border-radius:4px;background:#fffefb;font-size:13px}
.sheetcard::after{content:"";position:absolute;inset:0;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20width%3D%22300%22%20height%3D%22170%22%3E%3Ctext%20x%3D%22150%22%20y%3D%2295%22%20text-anchor%3D%22middle%22%20transform%3D%22rotate%28-28%20150%2085%29%22%20font-family%3D%22Big%20Shoulders%20Display%2C%20Impact%2C%20Arial%20Narrow%2C%20sans-serif%22%20font-weight%3D%22900%22%20font-size%3D%2240%22%20letter-spacing%3D%224%22%20fill%3D%22rgba%2813%2C34%2C48%2C0.075%29%22%3ERIP%20STIX%3C/text%3E%3C/svg%3E");background-size:300px 170px}
.dl-row{display:flex;gap:10px;flex-wrap:wrap}
.btn svg{width:18px;height:18px;margin-right:8px}
.sheetcard .sh-top{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1.5px solid var(--ink)}
.sheetcard .sh-top b{font-family:var(--f-display);font-weight:900;font-size:24px;line-height:1;background:var(--ink);color:#fff;padding:3px 10px}
.sheetcard dl{margin:0;display:grid;grid-template-columns:auto 1fr}
.sheetcard dt,.sheetcard dd{margin:0;padding:8px 12px;border-bottom:1px solid var(--line)}
.sheetcard dt{font-family:var(--f-mono);font-size:10.5px;letter-spacing:.08em;color:var(--ink-soft);text-transform:uppercase;border-right:1px solid var(--line)}
.sheetcard dd{min-width:0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
.sheetcard dd i{display:inline-block;width:12px;height:12px;border-radius:3px;vertical-align:-1px;margin-right:4px;border:1px solid rgba(0,0,0,.2)}
.copied{font-size:13px;color:#1f6b4f;min-height:20px}

/* ===== STATEMENT ===== */
.statement{position:relative;overflow:hidden;background:var(--deep)}
.st-inner{position:relative;min-height:100vh;display:grid;place-items:center;padding-block:80px}
.st-word{font-family:var(--f-display);font-weight:900;text-align:center;font-size:clamp(64px,15vw,240px);line-height:.82;color:var(--foam);text-wrap:balance}
.st-word em{font-style:normal;color:var(--sun)}
.st-board{position:absolute;left:50%;top:50%;height:min(84vh,780px);width:auto;transform:translate(-50%,-50%);filter:drop-shadow(0 40px 40px rgba(0,0,0,.5));pointer-events:none}
.st-note{position:absolute;left:var(--gut-l);right:var(--gut-r);bottom:28px;text-align:center;color:var(--mist);font-size:14px}

/* ===== RACK ===== */
.lineup{padding-block:110px 90px}
.feed{background:#0a1b26;padding-block:80px 76px}
.fd-in{max-width:1240px;margin:0 auto}
.feed-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:24px}
.feed-head h2{margin:4px 0 0;font-family:var(--f-display);font-weight:900;font-size:clamp(40px,5.6vw,76px);line-height:.88}
.feed-head h2 a{text-decoration:none}
.feed-head h2 a:hover{color:var(--sun)}
.follow{display:inline-flex;align-items:center;gap:8px;min-height:48px;padding:0 20px 0 16px;border-radius:999px;background:var(--foam);color:var(--deep);text-decoration:none;font-weight:700;font-size:14px}
.follow:hover{background:var(--sun)}
.feed-grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px}
.feed-grid a{position:relative;display:block;aspect-ratio:4/5;max-width:100%;overflow:hidden;background:#163447;border-radius:3px}
.feed-grid img{width:100%;height:100%;object-fit:cover;transition:transform .6s cubic-bezier(.2,.8,.2,1)}
.feed-grid a::after{content:"";position:absolute;inset:0;background:rgba(13,34,48,0);transition:background .25s}
.feed-grid a:hover img,.feed-grid a:focus-visible img{transform:scale(1.06)}
.feed-grid a:hover::after,.feed-grid a:focus-visible::after{background:rgba(13,34,48,.45)}
.feed-grid .ov{position:absolute;inset:auto 8px 8px 8px;z-index:2;display:flex;align-items:center;gap:6px;color:#fff;font-size:12px;line-height:1.4;opacity:0;transform:translateY(6px);transition:opacity .25s,transform .25s}
.feed-grid a:hover .ov,.feed-grid a:focus-visible .ov{opacity:1;transform:none}
.feed-grid .ov span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis;min-width:0}
.feed-grid .reel{position:absolute;top:8px;right:8px;z-index:2;width:22px;height:22px;color:#fff;filter:drop-shadow(0 1px 2px rgba(0,0,0,.5))}
.feed-note{margin:16px 0 0;font-size:12px;color:#6f8a96}
/* ===== TEAM ===== */
.team{background:var(--deep);padding-block:76px 70px}
.tm-in{max-width:1180px;margin:0 auto}
.tm-head{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:24px}
.tm-head h2{margin:4px 0 0;font-family:var(--f-display);font-weight:900;font-size:clamp(40px,5.6vw,76px);line-height:.88}
.tm-head p{margin:0;max-width:26em;color:#d9e4e6;font-size:14px}
.tm-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(14px,2vw,26px);align-items:start}
@media (min-width:861px) and (max-width:1099px){.tm-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
.rider{display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:10px;row-gap:4px;min-width:0;align-items:end}
.rider .rd-photo{grid-column:1/-1;margin-bottom:8px}
.rider .rd-thumbs{grid-column:2;grid-row:2;align-self:end}
.rider h3{grid-column:1;grid-row:2}
.rider .rd-ig{grid-column:1;grid-row:3}
.rider .rd-links{grid-column:1/-1;grid-row:3;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.rd-links .rd-ig{grid-column:auto;grid-row:auto}
.rd-web{position:relative;font-family:var(--f-body);font-size:14px;font-weight:900;letter-spacing:.01em;color:var(--deep);text-decoration:none;display:inline-flex;gap:8px;min-height:44px;align-items:center;padding:0 16px 0 12px;border-radius:999px;margin-top:4px;background:var(--sun);box-shadow:0 0 0 0 rgba(241,180,52,.6),0 6px 18px rgba(241,180,52,.35);animation:webPulse 2.2s ease-out infinite;transition:transform .2s,background .2s}
.rd-web .arr{width:16px;height:16px;flex:none;transition:transform .2s}
.rd-web:hover{background:#ffd166;transform:translateY(-2px)}
.rd-web:hover .arr{transform:translate(2px,-2px)}
@keyframes webPulse{0%{box-shadow:0 0 0 0 rgba(241,180,52,.55),0 6px 18px rgba(241,180,52,.35)}70%{box-shadow:0 0 0 12px rgba(241,180,52,0),0 6px 18px rgba(241,180,52,.35)}100%{box-shadow:0 0 0 0 rgba(241,180,52,0),0 6px 18px rgba(241,180,52,.35)}}
@media (prefers-reduced-motion:reduce){.rd-web{animation:none}}
.rider p{grid-column:1/-1;grid-row:4;margin-top:4px}
.rd-tags{display:none!important}
.rd-photo{margin:0;position:relative;aspect-ratio:4/3;max-width:100%;overflow:hidden;border-radius:4px;background:#163447}
.rd-photo img{width:100%;height:100%;object-fit:cover;transition:transform .8s cubic-bezier(.2,.8,.2,1),opacity .3s}
.rider:hover .rd-photo img{transform:scale(1.04)}
.rd-photo figcaption{position:absolute;left:10px;bottom:10px;font-family:var(--f-mono);font-size:10.5px;letter-spacing:.06em;background:rgba(13,34,48,.72);color:var(--foam);padding:3px 8px;border-radius:4px}
.rd-role{position:absolute;top:12px;left:12px;font-family:var(--f-mono);font-size:11px;letter-spacing:.14em;padding:5px 10px;border-radius:999px;background:var(--foam);color:var(--deep);font-weight:500}
.rider.pro .rd-role{background:var(--sun)}
.rd-thumbs{display:flex;gap:6px}
.rd-thumbs button{flex:0 0 40px;width:40px;height:40px;aspect-ratio:1;max-width:100%;padding:0;border:2px solid transparent;border-radius:4px;overflow:hidden;cursor:pointer;background:none;opacity:.6;transition:opacity .2s}
.rd-thumbs button[aria-pressed="true"]{border-color:var(--foam);opacity:1}
.rd-thumbs button:hover{opacity:1}
.rd-thumbs img{width:100%;height:100%;object-fit:cover}
.rider h3{margin:0;font-family:var(--f-display);font-weight:900;font-size:clamp(24px,2.1vw,32px);line-height:.9;letter-spacing:.01em}
.rd-ig{font-family:var(--f-mono);font-size:12.5px;font-weight:500;color:#fff;text-decoration:none;display:inline-flex;gap:7px;min-height:36px;align-items:center;justify-self:start;padding:0 14px 0 10px;border:0;border-radius:999px;margin-top:4px;background:radial-gradient(circle at 20% 115%,#fdf497 0%,#fdf497 6%,#fd5949 40%,#d6249f 62%,#285aeb 100%);box-shadow:0 4px 14px rgba(214,36,159,.28);transition:filter .2s,transform .2s}
.rd-ig:hover{filter:brightness(1.08);transform:translateY(-1px)}
.ig{width:18px;height:18px;flex:none}
.rider p{margin:0;color:#c9d7db;font-size:13px;line-height:1.65}
.rd-tags{display:flex;flex-wrap:wrap;gap:6px}
.rd-tags span{font-family:var(--f-mono);font-size:11px;padding:4px 8px;border:1px solid rgba(238,243,240,.3);border-radius:6px;color:#d9e4e6}
.lu-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:28px}
.lu-head h2{margin:0;font-family:var(--f-display);font-weight:900;font-size:clamp(56px,9vw,128px);line-height:.85}
.lu-head p{margin:0;max-width:24em;color:#d9e4e6}
.rack{display:flex;gap:clamp(8px,2vw,28px);align-items:flex-end;justify-content:center;overflow-x:auto;padding:40px 8px 0;scrollbar-width:none}
.rack::-webkit-scrollbar{display:none}
.rack button{flex:0 0 auto;border:0;background:none;padding:0 4px 26px;cursor:pointer;position:relative;transition:transform .45s cubic-bezier(.2,.8,.2,1)}
.rack img{height:clamp(240px,46vh,440px);width:auto;filter:drop-shadow(0 18px 18px rgba(0,0,0,.35)) saturate(.75) brightness(.85);transition:filter .45s}
.rack button::after{content:"";position:absolute;left:50%;bottom:6px;width:120%;height:14px;transform:translateX(-50%) scaleX(.4);border-radius:50%;background:rgba(0,0,0,.35);filter:blur(4px);transition:transform .45s,background .45s}
.rack button[aria-pressed="true"]{transform:translateY(-26px)}
.rack button[aria-pressed="true"] img{filter:drop-shadow(0 30px 26px rgba(0,0,0,.45))}
.rack button[aria-pressed="true"]::after{transform:translateX(-50%) translateY(26px) scaleX(1);background:rgba(0,0,0,.5)}
.card{margin:34px auto 0;max-width:760px;display:grid;grid-template-columns:1fr auto;gap:8px 24px;align-items:end;border-top:1px solid rgba(238,243,240,.3);padding-top:20px}
.card h3{margin:0;font-family:var(--f-display);font-weight:900;font-size:clamp(34px,5vw,56px);line-height:.95}
.card .sz{font-family:var(--f-mono);font-size:15px;font-variant-numeric:tabular-nums;text-align:right}
.card p{grid-column:1/-1;margin:0;color:#d9e4e6;min-width:0}
.card .tag{grid-column:1/-1;font-family:var(--f-mono);font-size:12px;letter-spacing:.12em;color:var(--sun);text-transform:uppercase}
.card .use{grid-column:1/-1;justify-self:start;margin-top:6px}

/* ===== ORDER ===== */
.order{background:var(--foam);color:var(--deep);padding-block:110px}
.order-grid{max-width:1180px;margin:0 auto;display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,5vw,72px);align-items:start}
.sheet{position:relative;transform:rotate(-2.5deg);box-shadow:0 30px 60px -20px rgba(13,34,48,.45);overflow:hidden;background:#fff;margin:0}
.sheet figcaption{position:absolute;right:10px;bottom:10px;background:var(--deep);color:var(--foam);font-family:var(--f-mono);font-size:11px;letter-spacing:.1em;padding:4px 8px;border-radius:4px}
.order h2{margin:4px 0 18px;font-family:var(--f-display);font-weight:900;font-size:clamp(52px,7vw,104px);line-height:.88}
.order .eyebrow{color:#4c6a78}
.order .lead{margin:0 0 28px;max-width:30em}
.flow{list-style:none;margin:0;padding:0;display:grid;counter-reset:f}
.flow li{counter-increment:f;display:grid;grid-template-columns:52px 1fr;gap:4px 14px;padding:16px 0;border-top:1px solid rgba(13,34,48,.18)}
.flow li::before{content:counter(f,decimal-leading-zero);font-family:var(--f-mono);font-size:14px;color:#9b3a64;padding-top:3px;grid-row:span 2}
.flow b{font-size:17px}
.flow span{color:#3a5562;font-size:15px}
.order .fine{margin:22px 0 0;font-size:14px;color:#4c6a78}

/* ===== COLUMN ===== */
.column{background:#fff;color:var(--ink);padding-block:100px}
.col-in{max-width:1180px;margin:0 auto}
.col-head{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(20px,4vw,60px);align-items:end;margin-bottom:30px}
.column .eyebrow{color:var(--ink-soft)}
.column h2{margin:4px 0 0;font-family:var(--f-display);font-weight:900;font-size:clamp(48px,6.6vw,96px);line-height:.88}
.col-head p{margin:0;color:#3a5562;max-width:34em}
.col-cards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px}
.col-cards a{display:flex;flex-direction:column;gap:6px;height:100%;padding:18px;border-radius:14px;background:var(--foam);color:var(--ink);text-decoration:none;border:1px solid transparent;transition:border-color .2s,transform .2s}
.col-cards a:hover{border-color:var(--ink);transform:translateY(-2px)}
.col-cards .cat{align-self:flex-start;font-size:11.5px;font-weight:700;color:#fff;background:#9b3a64;padding:2px 10px;border-radius:999px}
.col-cards b{font-size:17px;line-height:1.5}
.col-all{display:inline-flex;align-items:center;min-height:48px;margin-top:18px;padding:0 22px;border-radius:999px;background:var(--ink);color:#fff;font-weight:700;font-size:14px;text-decoration:none}
.col-all:hover{background:var(--sun);color:var(--ink)}
.home-faq{margin-top:56px;max-width:860px}
.home-faq h3{font-size:24px;margin:0 0 12px}
.home-faq details{background:var(--foam);border-radius:12px;margin:0 0 8px;padding:0 18px}
.home-faq summary{cursor:pointer;font-weight:700;padding:15px 26px 15px 0;list-style:none;position:relative}
.home-faq summary::-webkit-details-marker{display:none}
.home-faq summary::after{content:'+';position:absolute;right:0;top:13px;font-size:20px;color:var(--ink-soft)}
.home-faq details[open] summary::after{content:'−'}
.home-faq details p{margin:0 0 15px;color:#3a5562;font-size:15px}
@media (max-width:860px){.col-head{grid-template-columns:1fr}.column{padding-block:76px}}

/* ===== REPAIR ===== */
.repair{background:var(--deep);color:var(--foam);padding-block:110px}
.rp-in{max-width:1180px;margin:0 auto}
.rp-head{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,5vw,72px);align-items:end;margin-bottom:44px}
.repair .eyebrow{color:var(--mist)}
.repair h2{margin:4px 0 0;font-family:var(--f-display);font-weight:900;font-size:clamp(52px,7vw,104px);line-height:.88}
.repair h2 em{display:block;font-style:normal;color:var(--sun);font-family:var(--f-body);font-weight:900;font-size:.36em;line-height:1.25;margin-top:14px;letter-spacing:.02em}
.rp-lead{margin:0;font-size:16px;color:#c9d7dc;max-width:32em}
.rp-lead b{color:var(--foam)}
.rp-grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px}
.rp-grid li{display:grid;grid-template-columns:44px 1fr;gap:4px 14px;align-items:start;padding:18px;border-radius:14px;background:rgba(238,243,240,.06);border:1px solid rgba(238,243,240,.14)}
.rp-grid svg{width:44px;height:44px;grid-row:span 2;color:var(--sun)}
.rp-grid b{font-size:16px;line-height:1.4}
.rp-grid span{font-size:13.5px;color:#b7c8cf;line-height:1.7}
.rp-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:40px 0 0;padding:0;list-style:none;counter-reset:r}
.rp-flow li{counter-increment:r;padding-top:14px;border-top:2px solid rgba(238,243,240,.22)}
.rp-flow li::before{content:counter(r,decimal-leading-zero);display:block;font-family:var(--f-mono);font-size:13px;color:var(--sun);margin-bottom:4px}
.rp-flow b{display:block;font-size:16px}
.rp-flow span{font-size:13.5px;color:#b7c8cf}
.rp-foot{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:16px;margin-top:36px;align-items:start}
.rp-tip{margin:0;padding:16px 18px;border-radius:12px;background:#fff9ea;color:var(--ink);border:1px solid #e6c98a;font-size:14px}
.rp-tip b{display:block;color:#7a5410;margin-bottom:2px}
.rp-cta{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.rp-cta a{display:inline-flex;align-items:center;gap:8px;min-height:48px;padding:0 20px;border-radius:999px;font-weight:700;font-size:14px;text-decoration:none;background:var(--foam);color:var(--deep)}
.rp-cta a:hover{background:var(--sun)}
.rp-cta a.ghost{background:transparent;color:var(--foam);border:1px solid rgba(238,243,240,.5)}
.rp-cta a.ghost:hover{background:var(--foam);color:var(--deep)}
.rp-cta small{flex-basis:100%;color:#b7c8cf;font-size:13px}
@media (max-width:860px){.rp-head,.rp-foot{grid-template-columns:1fr}.rp-flow{grid-template-columns:repeat(2,minmax(0,1fr))}.repair{padding-block:80px}}

/* ===== SHOP ===== */
.access{background:var(--foam);color:var(--ink);padding-block:96px 90px}
.ac-in{max-width:1180px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:start}
.access .eyebrow{color:var(--ink-soft)}
.access h2{margin:4px 0 22px;font-family:var(--f-display);font-weight:900;font-size:clamp(48px,7vw,96px);line-height:.86}
.ac-info{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);column-gap:clamp(24px,4vw,56px);align-items:start}
.ac-info>.eyebrow,.ac-info>h2{grid-column:1/-1}
.ac-side{padding-top:6px}.ac-side .ac-note{margin-top:0}
@media (max-width:860px){.ac-info{grid-template-columns:1fr}.ac-side{padding-top:0}.ac-side .ac-note{margin-top:14px}}
.ac-list{margin:0;display:grid;grid-template-columns:auto 1fr;font-size:15px}
.ac-list dt,.ac-list dd{margin:0;padding:13px 0;border-bottom:1px solid var(--line)}
.ac-list dt{font-family:var(--f-mono);font-size:11.5px;letter-spacing:.1em;color:var(--ink-soft);padding-right:22px;padding-top:16px;white-space:nowrap}
.ac-list dd{min-width:0;overflow-wrap:anywhere}
.ac-list dd b{font-size:17px}
.ac-list .big{font-family:var(--f-mono);font-size:17px;font-variant-numeric:tabular-nums}
.ac-list small{display:block;color:var(--ink-soft);font-size:12.5px;margin-top:2px}
.ac-note{margin:14px 0 0;font-size:12.5px;color:#7a5410}
.ac-btns{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}
.ac-btns a,.ac-btns button{display:inline-flex;align-items:center;gap:8px;min-height:46px;padding:0 18px 0 14px;border-radius:999px;font-size:14px;font-weight:700;text-decoration:none;cursor:pointer;border:1px solid var(--ink);background:#fff;color:var(--ink)}
.ac-btns a.pri{background:var(--ink);color:#fff}
.ac-btns a:hover,.ac-btns button:hover{background:var(--sun);border-color:var(--sun);color:var(--ink)}
.ac-btns svg{width:18px;height:18px;flex:none}
.ac-copied{font-size:12.5px;color:#1f6b4f;min-height:18px;margin-top:6px}
.map-card{position:relative;border-radius:14px;overflow:hidden;background:#bcd9e6;border:1px solid var(--line);box-shadow:0 24px 50px -28px rgba(13,34,48,.45)}
.map-view{position:relative;aspect-ratio:3/2;max-width:100%;touch-action:none;cursor:grab;user-select:none}
.map-view.dragging{cursor:grabbing}
.map-view>svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.map-view iframe{position:absolute;inset:0;width:100%;height:100%;border:0;z-index:5;background:#e8eef0}
.map-card.is-google .map-view{cursor:auto;touch-action:auto}
.map-card.is-google .map-ctl,.map-card.is-google .map-credit,.map-card.is-google .map-legend{display:none}
.ac-map{grid-column:1/-1}
.ac-map .map-view{aspect-ratio:16/5.4}
@media (max-width:860px){.ac-map .map-view{aspect-ratio:4/3.4}}
.map-ctl{position:absolute;right:10px;top:10px;display:grid;gap:6px;z-index:3}
.map-ctl button{width:40px;height:40px;border-radius:10px;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:20px;line-height:1;cursor:pointer;display:grid;place-items:center;box-shadow:0 4px 10px rgba(13,34,48,.12)}
.map-ctl button:hover{background:var(--sun)}
.map-ctl svg{width:18px;height:18px}
.map-legend{display:flex;flex-wrap:wrap;gap:6px 14px;padding:10px 14px;background:#fff;font-size:12px;color:var(--ink-soft);border-top:1px solid var(--line)}
.map-legend span{display:inline-flex;align-items:center;gap:6px}
.map-legend i{display:inline-block;width:18px;height:4px;border-radius:2px}
.map-credit{position:absolute;left:10px;bottom:8px;z-index:3;font-size:10.5px;color:var(--ink-soft);background:rgba(255,255,255,.8);padding:2px 8px;border-radius:999px;pointer-events:none}
.map-tip{position:absolute;z-index:4;transform:translate(-50%,-100%);background:var(--ink);color:#fff;font-size:12px;padding:6px 10px;border-radius:8px;white-space:nowrap;pointer-events:none;margin-top:-12px}
@media (max-width:860px){.ac-in{grid-template-columns:1fr}.access{padding-block:70px 64px}}

/* ===== members / my page / admin ===== */
.acct-btn{display:inline-flex;align-items:center;gap:7px;min-height:44px;padding:0 14px 0 11px;border-radius:999px;border:1px solid rgba(238,243,240,.45);background:rgba(13,34,48,.35);color:var(--foam);font-weight:700;font-size:13px;cursor:pointer;white-space:nowrap;backdrop-filter:blur(6px);max-width:170px}
.acct-btn:hover{background:var(--foam);color:var(--deep)}
.acct-btn svg{width:18px;height:18px;flex:none}
.acct-btn span{overflow:hidden;text-overflow:ellipsis}
@media (max-width:560px){.acct-btn{width:44px;padding:0;justify-content:center}.acct-btn span{display:none}}
html.ac-open,html.ac-open body{overflow:hidden}
.acct{position:fixed;inset:0;z-index:130;background:var(--studio);color:var(--ink);color-scheme:light;overflow-y:auto;overscroll-behavior:contain}
.ac-bar{position:sticky;top:0;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:10px max(16px,env(safe-area-inset-right,0px)) 10px max(16px,env(safe-area-inset-left,0px));background:rgba(230,236,238,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.ac-bar .l{display:flex;align-items:center;gap:12px;min-width:0}
.ac-bar h2{white-space:nowrap;margin:0;font-family:var(--f-display);font-weight:900;font-size:28px;line-height:1;letter-spacing:.02em}
.ac-bar .r{display:flex;gap:8px;flex-wrap:wrap}
.ac-chip{display:inline-flex;align-items:center;min-height:26px;padding:0 10px;border-radius:999px;font-family:var(--f-mono);font-size:11px;letter-spacing:.06em;background:#fff;border:1px solid var(--line);color:var(--ink-soft)}
.ac-chip.warn{background:#fff9ea;border-color:#e6c98a;color:#7a5410}
.ac-in{max-width:1080px;margin:0 auto;padding:22px 16px 80px}
.ac-hello{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:16px}
.ac-hello h3{margin:0;font-size:clamp(22px,3vw,30px);line-height:1.3}
.ac-hello p{margin:2px 0 0;color:var(--ink-soft);font-size:13px}
.ac-tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);margin-bottom:18px;overflow-x:auto}
.ac-tabs button{min-height:44px;padding:0 16px;border:0;background:none;font:inherit;font-weight:700;font-size:14px;color:var(--ink-soft);cursor:pointer;border-bottom:3px solid transparent;white-space:nowrap}
.ac-tabs button[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--sun)}
.ac-tabs b{font-family:var(--f-mono);font-weight:500;font-size:12px;margin-left:6px;color:var(--ink-soft)}
.ac-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px}
.ac-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px}
.ac-board{display:grid;grid-template-columns:62px 1fr;gap:14px;align-items:start}
.ac-thumb{height:150px;display:flex;align-items:center;justify-content:center;gap:4px;background:linear-gradient(#f3f6f7,#e7edef);border-radius:10px;padding:8px 4px}
.ac-thumb svg{height:100%;width:auto;max-width:100%}
.ac-board h4{margin:0 0 2px;font-size:15px;line-height:1.4}
.ac-meta{font-family:var(--f-mono);font-size:11.5px;color:var(--ink-soft);letter-spacing:.02em;line-height:1.6}
.ac-acts{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.ac-acts .btn{min-height:38px;padding:0 13px;font-size:12.5px}
.btn.danger{background:#fff;color:#b3261e;border-color:#e3b1ad}
.btn.danger.armed{background:#b3261e;color:#fff;border-color:#b3261e}
.ac-empty{padding:32px 18px;text-align:center;color:var(--ink-soft);border:1.5px dashed var(--line);border-radius:14px;background:rgba(255,255,255,.5)}
.ac-empty .btn{margin-top:12px}
.ac-order{display:grid;grid-template-columns:62px 1fr;gap:14px}
.ac-order + .ac-order{margin-top:12px}
.ac-no{font-family:var(--f-mono);font-size:13px;font-weight:500;letter-spacing:.04em}
.ac-steps{display:flex;gap:3px;margin:10px 0 4px;flex-wrap:wrap}
.ac-steps span{flex:1 1 0;min-width:52px;font-size:10.5px;text-align:center;padding:5px 2px;border-radius:6px;background:#eef2f3;color:#7d909a;white-space:nowrap}
.ac-steps span.done{background:#d9efe5;color:#1f6b4f}
.ac-steps span.now{background:var(--ink);color:#fff;font-weight:700}
.ac-cancel{display:inline-block;margin-top:8px;font-size:12px;color:#b3261e;font-weight:700}
.ac-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 16px}
.ac-form .full{grid-column:1/-1}
.ac-form label{display:grid;gap:5px;font-size:12.5px;font-weight:700;color:var(--ink-soft)}
.ac-form label>span{display:flex;align-items:center;gap:2px}
.ac-form label i{font-style:normal;color:#b3261e;margin-left:3px}
.ac-form input,.ac-form select,.ac-form textarea,.ac-search input,.ac-mini input,.ac-mini select,.ac-mini textarea{font:inherit;font-size:16px;color:var(--ink);background:#fff;border:1px solid rgba(13,34,48,.28);border-radius:10px;padding:10px 12px;min-height:46px;width:100%}
.ac-form textarea,.ac-mini textarea{min-height:90px;resize:vertical}
.ac-form input:focus,.ac-form select:focus,.ac-form textarea:focus,.ac-search input:focus,.ac-mini input:focus,.ac-mini select:focus,.ac-mini textarea:focus{outline:2px solid var(--sun);outline-offset:1px;border-color:var(--ink)}
.ac-form .chk{display:flex;align-items:flex-start;gap:10px;font-weight:400;color:var(--ink);font-size:13.5px}
.ac-form .chk input{width:20px;height:20px;min-height:0;margin-top:3px;flex:none}
.ac-err{color:#b3261e;font-size:13px;font-weight:700;min-height:20px}
.ac-ok{color:#1f6b4f;font-size:13px;font-weight:700;min-height:20px}
.ac-form .err input,.ac-form .err select{border-color:#b3261e;background:#fff7f6}
.ac-note{font-size:12.5px;color:var(--ink-soft);margin:6px 0 0}
.ac-sum{display:grid;grid-template-columns:auto 1fr;gap:20px;align-items:start}
.ac-sum .ac-thumb{width:150px;height:260px}
.ac-pre{white-space:pre-wrap;font-size:13px;line-height:1.75;margin:0;font-family:var(--f-body)}
.ac-done{text-align:center;padding:30px 18px}
.ac-done b{display:block;font-family:var(--f-mono);font-size:22px;letter-spacing:.06em;margin:6px 0 10px}
/* admin */
.ac-search{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px}
.ac-search .q{position:relative;flex:1 1 280px}
.ac-search .q input{padding-left:40px}
.ac-search .q svg{position:absolute;left:13px;top:50%;width:18px;height:18px;transform:translateY(-50%);color:var(--ink-soft);pointer-events:none}
.ac-seg{display:inline-flex;border:1px solid var(--line);border-radius:999px;overflow:hidden;background:#fff}
.ac-seg button{min-height:44px;padding:0 14px;border:0;background:none;font:inherit;font-size:13px;font-weight:700;color:var(--ink-soft);cursor:pointer}
.ac-seg button[aria-pressed="true"]{background:var(--ink);color:#fff}
.ac-stats{display:flex;gap:18px;flex-wrap:wrap;font-size:12.5px;color:var(--ink-soft);margin:0 0 10px}
.ac-stats b{font-family:var(--f-mono);font-size:15px;color:var(--ink);margin-right:3px}
.ac-table{color:var(--ink);font-family:var(--f-body);width:100%;border-collapse:collapse;background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;font-size:14px}
.ac-table th{text-align:left;font-family:var(--f-mono);font-weight:500;font-size:11px;letter-spacing:.08em;color:var(--ink-soft);padding:10px 12px;background:#f4f7f8;border-bottom:1px solid var(--line);white-space:nowrap}
.ac-table td{padding:12px;border-bottom:1px solid var(--line);vertical-align:middle}
.ac-table tr:last-child td{border-bottom:0}
.ac-table tbody tr{cursor:pointer}
.ac-table tbody tr:hover,.ac-table tbody tr:focus-visible{background:#fffbea;outline:none}
.ac-table .nm b{display:block;font-size:15px}
.ac-table .nm small{color:var(--ink-soft);font-size:12px}
.ac-table .mono{font-family:var(--f-mono);font-size:12.5px;white-space:nowrap}
.ac-kind{display:inline-block;font-size:11px;font-weight:700;padding:2px 8px;border-radius:999px;background:#e3f0f6;color:#1d5a78;white-space:nowrap}
.ac-kind.w{background:#f3ece0;color:#7a5410}
mark{background:#ffe7a3;color:inherit;border-radius:3px;padding:0 1px}
.ac-detail{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.35fr);gap:16px;align-items:start}
.ac-detail h4{margin:0 0 10px;font-family:var(--f-mono);font-weight:500;font-size:12px;letter-spacing:.1em;color:var(--ink-soft)}
.ac-detail section + section{margin-top:16px}
.ac-dl{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;margin:0;font-size:14px}
.ac-dl dt{color:var(--ink-soft);font-size:12.5px;white-space:nowrap}
.ac-dl dd{margin:0;overflow-wrap:anywhere}
.ac-hist{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.ac-hist li{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:start;padding:10px 12px;background:#f7f9fa;border-radius:10px;font-size:13.5px}
.ac-hist .d{font-family:var(--f-mono);font-size:12px;color:var(--ink-soft);white-space:nowrap;padding-top:2px}
.ac-mini{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:10px}
.ac-mini .full{grid-column:1/-1}
.ac-mini input,.ac-mini select{min-height:42px;font-size:15px;padding:8px 10px}
.ac-st{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:8px}
.ac-st select{font:inherit;font-size:14px;min-height:40px;border-radius:10px;border:1px solid rgba(13,34,48,.28);padding:0 10px;background:#fff}
.ac-back{display:inline-flex;align-items:center;gap:6px;min-height:44px;border:0;background:none;font:inherit;font-weight:700;color:var(--ink);cursor:pointer;padding:0;margin-bottom:10px}
.ac-back svg{width:16px;height:16px}
.ac-auth{max-width:560px;margin:0 auto}
.ac-pw{position:relative;display:block}
.ac-pw input{padding-right:70px}
.ac-eye{position:absolute;right:6px;top:50%;transform:translateY(-50%);min-height:36px;min-width:52px;padding:0 10px;border:0;background:#eef2f3;border-radius:8px;font:inherit;font-size:12px;font-weight:700;cursor:pointer;color:var(--ink)}
.ac-eye:hover{background:var(--sun)}
.ac-hint{font-weight:400;color:var(--ink-soft);font-size:12px}
.ac-link{border:0;background:none;font:inherit;font-size:14px;font-weight:700;color:var(--ink);text-decoration:underline;text-underline-offset:3px;cursor:pointer;padding:0;min-height:44px}
.ac-link:disabled{color:var(--ink-soft);text-decoration:none;cursor:default}
.ac-join{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-top:14px}
.ac-join b{font-size:15px}.ac-join p{margin:2px 0 0;font-size:13px;color:var(--ink-soft)}
.ac-flash{background:#e6f4ee;border:1px solid #b5dcc9;color:#1f6b4f;padding:10px 14px;border-radius:10px;font-size:13.5px;font-weight:700;margin-bottom:14px}
.ac-stepper{display:flex;gap:6px;margin-bottom:10px}
.ac-stepper span{flex:1;text-align:center;font-size:12px;font-weight:700;padding:6px 4px;border-radius:8px;background:#eef2f3;color:var(--ink-soft)}
.ac-stepper span.on{background:var(--ink);color:#fff}
.ac-mail{border:1.5px dashed #c9a24a;background:#fffdf6;border-radius:12px;padding:14px 16px;margin:0 0 14px;font-size:13.5px}
.ac-mail p{margin:8px 0}
.ac-mail-tag{display:inline-block;font-size:11px;font-weight:700;color:#7a5410;background:#fff1cc;border-radius:999px;padding:2px 10px;margin-bottom:8px}
.ac-mail-h{font-size:12.5px;color:var(--ink-soft);line-height:1.8}.ac-mail-h b{display:inline-block;width:3.2em;color:var(--ink)}
.ac-mail .code{font-family:var(--f-mono);font-size:30px;letter-spacing:.32em;font-weight:500;color:var(--ink);margin:4px 0}
.ac-codein{font-family:var(--f-mono)!important;font-size:22px!important;letter-spacing:.3em}
.ac-ro{background:#f1f4f5!important;color:var(--ink-soft)!important}
.cf-acct{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px;border-radius:12px;background:#fff;border:1px solid var(--line);margin:4px 0 12px}
.cf-acct p{margin:0;flex:1 1 220px;font-size:13px;color:var(--ink-soft)}
.cf-acct .btn{min-height:44px}
.cf-acct-msg{flex-basis:100%;font-size:13px;font-weight:700;color:#1f6b4f;min-height:0}
.cf-acct-msg:empty{display:none}
.cf-acct-msg button{border:0;background:none;color:var(--ink);text-decoration:underline;font:inherit;cursor:pointer;padding:0;margin-left:6px}
@media (max-width:760px){
  .ac-bar h2{font-size:24px}.ac-chip{font-size:10px}
  .ac-form,.ac-mini{grid-template-columns:1fr}
  .ac-detail{grid-template-columns:1fr}
  .ac-sum{grid-template-columns:1fr}.ac-sum .ac-thumb{width:100%;height:220px}
  .ac-table thead{display:none}
  .ac-table,.ac-table tbody,.ac-table tr,.ac-table td{display:block;width:100%}
  .ac-table tr{border-bottom:1px solid var(--line);padding:10px 12px}
  .ac-table td{border:0;padding:2px 0}
  .ac-table td.hide-sm{display:none}
}
.shop{background:var(--deep);padding-block:100px calc(60px + env(safe-area-inset-bottom,0px))}
.shop-in{max-width:1180px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:40px;align-items:end}
.shop h2{margin:6px 0 0;font-family:var(--f-display);font-weight:900;font-size:clamp(60px,11vw,170px);line-height:.82}
.shop h2 em{font-style:normal;color:var(--sun)}
.shop dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:10px 18px;font-size:15px}
.shop dt{font-family:var(--f-mono);font-size:12px;letter-spacing:.12em;color:var(--mist);padding-top:3px}
.shop dd{margin:0;min-width:0;overflow-wrap:anywhere}
.links{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}
.links a{display:inline-flex;align-items:center;min-height:44px;padding:0 18px;border:1px solid rgba(238,243,240,.4);border-radius:999px;text-decoration:none;font-size:14px}
.links a:hover{background:var(--foam);color:var(--deep)}
.company{max-width:1180px;margin:72px auto 0;padding-top:36px;border-top:1px solid rgba(238,243,240,.18);display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:24px 48px;align-items:start}
.company h3{margin:4px 0 0;font-family:var(--f-display);font-weight:900;font-size:clamp(34px,4vw,52px);line-height:.9}
.company dl{margin:0;display:grid;grid-template-columns:auto 1fr;font-size:15px}
.company dt,.company dd{margin:0;padding:14px 0;border-bottom:1px solid rgba(238,243,240,.14)}
.company dt{font-family:var(--f-mono);font-size:12px;letter-spacing:.1em;color:var(--mist);padding-right:28px;padding-top:17px}
.company dd{min-width:0;overflow-wrap:anywhere}
.company dd b{font-size:17px}
.company .tel{color:var(--foam);text-decoration:none;font-family:var(--f-mono);font-size:17px;font-variant-numeric:tabular-nums;border-bottom:1px solid rgba(238,243,240,.4)}
.company .tel:hover{color:var(--sun);border-color:var(--sun)}
@media (max-width:860px){.company{grid-template-columns:1fr;margin-top:56px}}
.credit{max-width:1180px;margin:56px auto 0;font-family:var(--f-mono);font-size:11px;letter-spacing:.08em;color:#6f8a96}
.sources{max-width:1180px;margin:14px auto 0;font-size:12px;color:#6f8a96}
.sources a{color:#8fa9b4}

@media (max-width:860px){
  .logo small{display:none}
  .top .cta{padding:0 14px;font-size:13px}
  .menu-in{grid-template-columns:1fr;align-items:start}
  .menu-boards{height:130px}
  .wall{top:auto;height:46vh;bottom:calc(190px + env(safe-area-inset-bottom,0px))}
  .wall .bd{margin:0 -6vw}
  .hero-word{font-size:34vw}
  .types{--slide:46vw}
  .ts-hint{display:none}
  .ts-word{top:calc(var(--head) + 70px);font-size:30vw}
  .ts-stage{height:46vh;min-height:300px}
  .ts-arrow{display:none}
  .ts-tabs{gap:4px;margin-bottom:18px}
  .ts-tabs button{padding:0 10px;font-size:11px}
  .ts-info{grid-template-columns:1fr}
  .ts-info h3{font-size:44px}
  .ts-info p{font-size:14px}
  .custom{overflow-y:auto;overscroll-behavior:contain;scroll-padding-top:calc(54vh + 64px)}
  .cf{display:block;height:auto}
  .cf-stage{position:sticky;top:0;height:54vh;z-index:4;border-bottom:1px solid var(--line)}
  .cf-bar{padding:8px 12px 0}
  .cf-bar .eyebrow{display:none}
  .cf-panel{height:auto;overflow:visible}
  .bc-in{grid-template-columns:1fr}
  .bc-copy{padding-bottom:10px}
  .fan-deck{--step:6.6deg;height:clamp(300px,80vw,420px)}
  .fd-read{right:auto;left:0;top:auto;bottom:-6px;text-align:left}
  .fd-count{display:none}
  .cf-read{padding:2px 10px 8px;gap:14px}
  .cf-read b{font-size:20px}
  .cf-panel{border-left:0;padding-top:12px}
  .steps-nav{top:54vh;margin:0 12px}
  .pane{padding:18px 16px 0}
  .next{padding:6px 16px 0}
  .order-grid,.shop-in{grid-template-columns:1fr}
  .feed-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}
  .feed-grid .ov{display:none}
  .feed{padding-block:60px 56px}
  .tm-grid{display:flex;gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;margin-inline:calc(-1 * var(--gut-l)) calc(-1 * var(--gut-r));padding-inline:var(--gut-l) var(--gut-r)}
  .tm-grid::-webkit-scrollbar{display:none}
  .tm-grid .rider{flex:0 0 78vw;scroll-snap-align:start}
  .team{padding-block:60px 56px}
  .sheet{transform:rotate(-1.5deg)}
  .card{grid-template-columns:1fr}
  .card .sz{text-align:left}
}
@media (prefers-reduced-motion:reduce){
  .scroll-cue i{animation:none}
  body,.rack button,.rack img{transition:none}
}
