/* ================= GEOMETRY ================= */
function monoSpline(xs,ys){
  var n=xs.length,d=[],m=[],i;
  for(i=0;i<n-1;i++)d[i]=(ys[i+1]-ys[i])/(xs[i+1]-xs[i]);
  m[0]=d[0];m[n-1]=d[n-2];
  for(i=1;i<n-1;i++)m[i]=(d[i-1]*d[i]<=0)?0:(d[i-1]+d[i])/2;
  for(i=0;i<n-1;i++){if(d[i]===0){m[i]=m[i+1]=0;continue}var a=m[i]/d[i],b=m[i+1]/d[i],s=a*a+b*b;if(s>9){var t=3/Math.sqrt(s);m[i]=t*a*d[i];m[i+1]=t*b*d[i]}}
  return function(x){
    if(x<=xs[0])return ys[0];if(x>=xs[n-1])return ys[n-1];
    var k=0;while(x>xs[k+1])k++;
    var hh=xs[k+1]-xs[k],t=(x-xs[k])/hh,t2=t*t,t3=t2*t;
    return (2*t3-3*t2+1)*ys[k]+(t3-2*t2+t)*hh*m[k]+(-2*t3+3*t2)*ys[k+1]+(t3-t2)*hh*m[k+1];
  };
}
function tailEnd(type,tail){return TAILS[tail].frac*(type.id==='fish'?1.35:type.id==='long'?1.12:type.id==='grov'?1.12:1)}
function capDepth(tail,tw){
  switch(tail){case 'roundpin':return Math.max(tw*1.2,.8);case 'round':return tw*.85;case 'squash':return Math.min(.9,tw*.45);case 'square':return .2;
  case 'diamond':return 1.1;case 'swallow':case 'fish':return .3;default:return .6}
}
function makeProfile(type,tail,W,L){
  var tw=tailEnd(type,tail)*W/2,cd=capDepth(tail,tw),Le=L-cd;
  var xs=type.prof.map(function(p){return p[0]}),ys=type.prof.map(function(p,i){return i===type.prof.length-1?tailEnd(type,tail):p[1]});
  var f=monoSpline(xs,ys);
  return {f:f,tw:tw,Le:Le,L:L,W:W,hw:function(y){if(y<=0)return 0;if(y>=Le)return tw;return f(y/Le)*W/2}};
}
function resample(poly,K){
  var cum=[0],i;for(i=1;i<poly.length;i++)cum[i]=cum[i-1]+Math.hypot(poly[i][0]-poly[i-1][0],poly[i][1]-poly[i-1][1]);
  var tot=cum[cum.length-1],out=[],j=0;
  for(var k=1;k<=K;k++){var s=tot*k/(K+1);while(cum[j+1]<s)j++;var t=(s-cum[j])/((cum[j+1]-cum[j])||1);out.push([lerp(poly[j][0],poly[j+1][0],t),lerp(poly[j][1],poly[j+1][1],t)])}
  return out;
}
function arc(cx,cy,rx,ry,a0,a1,n){var p=[];for(var i=0;i<=n;i++){var a=lerp(a0,a1,i/n);p.push([cx+rx*Math.cos(a),cy+ry*Math.sin(a)])}return p}
function capPoly(tail,tw,Le,L){
  var p;
  switch(tail){
    case 'squash':case 'square':var r=tail==='square'?.2:Math.min(.9,tw*.45);
      p=arc(tw-r,Le,r,r,0,Math.PI/2,8).concat(arc(-(tw-r),Le,r,r,Math.PI/2,Math.PI,8));break;
    case 'swallow':case 'fish':var notch=tail==='fish'?4.2:2.2,tip=tail==='fish'?.72:.8;
      p=arc(tw*tip,Le,tw*(1-tip),.3,0,Math.PI/2,6).concat([[0,L-notch]]).concat(arc(-tw*tip,Le,tw*(1-tip),.3,Math.PI/2,Math.PI,6));break;
    case 'diamond':p=[[tw,Le],[tw*.32,L],[-tw*.32,L],[-tw,Le]];break;
    default:p=arc(0,Le,tw,L-Le,0,Math.PI,24);
  }
  return [[tw,Le]].concat(p).concat([[-tw,Le]]);
}
var NSIDE=80,NCAP=30;
/* Round pin, built from shaping references: the tail stays full (about 70-74% of the wide point measured
   12" up from the tail) and then curves continuously, convex all the way, into a rounded point.
   One cubic Bezier carries the rail's own direction into a tip with a horizontal tangent. */
/* round pin (default) and round tail (opt.round): the rail flows into one smooth curve that closes at the tail */
function roundPinOutline(type,W,L,opt){
  opt=opt||{};
  var ys=type.prof.map(function(p,i){return i===type.prof.length-1?TAILS.squash.frac:p[1]}),f=monoSpline(type.prof.map(function(p){return p[0]}),ys);
  var S=opt.round?clamp(L*0.2,13,20):clamp(L*0.36,20,32),y0=L-S,x0=f(y0/L)*W/2,dy=0.5,m0=(f((y0+dy)/L)-f((y0-dy)/L))*W/2/(2*dy);
  var full=opt.round?0.8:(type.id==='mid'||type.id==='long')?0.68:0.72,x12=Math.min(full*W/2,x0*0.97),b=(opt.round?0.17:0.085)*W;
  var n=Math.hypot(m0,1),dx=m0/n,dyv=1/n;
  function bez(a,steps){var P1=[x0+dx*a,y0+dyv*a],P2=[b,L],P3=[0,L],out=[];for(var k=1;k<=steps;k++){var t=k/steps,u=1-t;
    out.push([u*u*u*x0+3*u*u*t*P1[0]+3*u*t*t*P2[0]+t*t*t*P3[0],u*u*u*y0+3*u*u*t*P1[1]+3*u*t*t*P2[1]+t*t*t*P3[1]])}return out}
  function xAt(pts,y){var prev=[x0,y0];for(var k=0;k<pts.length;k++){var q=pts[k];if(q[1]>=y){var tt=(y-prev[1])/((q[1]-prev[1])||1);return lerp(prev[0],q[0],tt)}prev=q}return 0}
  var lo=1,hi=S*1.4;for(var it=0;it<40;it++){var mid=(lo+hi)/2;if(xAt(bez(mid,120),L-12)<x12)lo=mid;else hi=mid}
  var tail=bez((lo+hi)/2,44),right=[],i;
  for(i=0;i<NSIDE;i++){var u=i/(NSIDE-1),s=(1-Math.cos(Math.PI*u))/2,y=s*y0;right.push([f(y/L)*W/2,y])}
  right=right.concat(tail);var tip=right.pop();
  var left=right.slice().reverse().map(function(p){return[-p[0],p[1]]});
  var P={f:f,tw:b,Le:L,L:L,W:W,hw:function(y){if(y<=0)return 0;if(y>=L)return 0;return y<=y0?f(y/L)*W/2:xAt(tail,y)}};
  return {pts:right.concat([tip]).concat(left),P:P};
}
function outline(type,tail,W,L){
  if(tail==='roundpin')return roundPinOutline(type,W,L);
  if(tail==='round')return roundPinOutline(type,W,L,{round:true});
  var P=makeProfile(type,tail,W,L),right=[],i;
  for(i=0;i<NSIDE;i++){var u=i/(NSIDE-1),s=(1-Math.cos(Math.PI*u))/2,y=s*P.Le;right.push([P.f(s)*W/2,y])}
  var cap=resample(capPoly(tail,P.tw,P.Le,L),NCAP);
  var left=right.slice().reverse().map(function(p){return[-p[0],p[1]]});
  return {pts:right.concat(cap).concat(left),P:P};
}
function pathD(pts,dx,dy){dx=dx||0;dy=dy||0;var s='M';for(var i=0;i<pts.length;i++)s+=(i?'L':'')+(pts[i][0]+dx).toFixed(2)+' '+(pts[i][1]+dy).toFixed(2);return s+'Z'}
function lerpPts(a,b,t){return a.map(function(p,i){return[lerp(p[0],b[i][0],t),lerp(p[1],b[i][1],t)]})}

/* ================= FORMAT ================= */
function ftIn(inch){var f=Math.floor(inch/12),r=Math.round(inch-f*12);if(r===12){f++;r=0}return f+"'"+r+'"'}
function frac(v){var w=Math.floor(v+1e-6),r=v-w,e=Math.round(r*16);if(e===16){w++;e=0}if(!e)return w+'"';var g=function(a,b){return b?g(b,a%b):a},k=g(e,16);return w+' '+(e/k)+'/'+(16/k)+'"'}
function cm(inch){return (inch*2.54).toFixed(1)+'cm'}
function vol(c){var t=TYPE_BY[c.type];return c.L*c.W*c.T*0.0163871*t.k}

