var DEFAULT={type:'mid',L:84,W:21,T:2.75,tail:'roundpin',fin:'twoplusone',sys:'FCS II',pat:'railfade',deck:'#f4f3ee',accent:'#3fbf8f',pinColor:'#16191c',pin:false,botSame:true,bottom:'#f4f3ee',finColor:'#3a4045',str:'wood',logoD:{on:true,logo:'coffin',ori:'h',color:'#16191c',pos:{u:0,t:.3}},logoB:{on:true,logo:'label',ori:'h',color:'#16191c',pos:{u:0,t:.6}}};
