function isHex(v){return typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v)}
function num(v,lo,hi,d){v=typeof v==='string'?parseFloat(v):v;return (typeof v==='number'&&isFinite(v))?clamp(v,lo,hi):d}
function cleanLogo(o,d){o=(o&&typeof o==='object')?o:{};var ids=LOGOS.map(function(l){return l.id}),p=(o.pos&&typeof o.pos==='object')?o.pos:{};
  return {on:typeof o.on==='boolean'?o.on:d.on,logo:ids.indexOf(o.logo)>=0?o.logo:d.logo,ori:o.ori==='v'||o.ori==='h'?o.ori:d.ori,color:isHex(o.color)?o.color:d.color,pos:{u:num(p.u,-1,1,d.pos.u),t:num(p.t,.07,.86,d.pos.t)}}}
/* make any stored or incoming config safe to render: unknown values fall back to defaults, numbers are clamped to the type's range */
function sanitize(c){
  c=(c&&typeof c==='object'&&!Array.isArray(c))?c:{};var o=JSON.parse(JSON.stringify(DEFAULT));
  var t=TYPE_BY[c.type]||TYPE_BY[o.type];o.type=t.id;
  o.L=num(c.L,t.LR[0],t.LR[1],t.L[2]);o.W=num(c.W,t.WR[0],t.WR[1],t.W[2]);o.T=num(c.T,t.TR[0],t.TR[1],t.T[2]);
  o.tail=t.tails.indexOf(c.tail)>=0?c.tail:t.tails[0];o.fin=t.fins.indexOf(c.fin)>=0?c.fin:t.fins[0];
  o.sys=SYSTEMS.indexOf(c.sys)>=0?c.sys:o.sys;o.pat=PATTERNS.some(function(p){return p.id===c.pat})?c.pat:o.pat;
  ['deck','accent','pinColor','bottom','finColor'].forEach(function(k){if(isHex(c[k]))o[k]=c[k]});
  if(typeof c.botSame==='boolean')o.botSame=c.botSame;
  o.str=STRINGERS.some(function(x){return x.id===c.str})?c.str:o.str;
  if(!c.logoD&&c.logo)c.logoD={on:true,logo:c.logo,ori:c.ori,color:c.logoColor,pos:c.pos};
  o.logoD=cleanLogo(c.logoD,DEFAULT.logoD);o.logoB=cleanLogo(c.logoB,DEFAULT.logoB);
  return o;
}
