function setType(id){var t=TYPE_BY[id];cfg.type=id;cfg.L=t.L[2];cfg.W=t.W[2];cfg.T=t.T[2];cfg.tail=t.tails[0];cfg.fin=t.fins[0];}

/* ================= BOARD RENDER ================= */
var uid=0;
/* Fin templates from published specs (inches, sweep in degrees):
   FCS II Performer M  base 4.37 / depth 4.55 / sweep 33.7  (thruster, 5-fin and quad fronts)
   FCS II Pivot 7"     base 4.88 / depth 7.01 / sweep 27.1  (single; scaled to 8" and 9" on longer boards)
   FCS II Modern Keel  base 6.41 / depth 5.50 / sweep 32.8  (twin)
   quad rears, 2+1 side bites and the twin's stabiliser are smaller fins of the same family.
   r = tip radius as a share of depth: fins end in a rounded tip, not a point.
   g = outline fullness [lead bulge, lead lay-back, trailing hook, trailing base x, trailing base height], tuned so each
   outline's area matches the published figure (Performer 14.8, Pivot 7" 22.9, Modern Keel 25.1 sq in). */
var FIN_TPL={
  perf:{B:4.37,D:4.55,sw:33.7,r:.085,foil:.27},
  qrear:{B:3.95,D:4.05,sw:31.5,r:.09,foil:.24},
  bite:{B:3.1,D:2.85,sw:30,r:.12,foil:.22},
  stab:{B:2.6,D:2.4,sw:28,r:.13,foil:.22},
  keel:{B:6.41,D:5.5,sw:32.8,r:.13,foil:.3,keel:true},
  pivot:{B:4.88,D:7.01,sw:27.1,r:.065,foil:.36,g:[.35,.25,.45,-.2,.55]}
};
function singleTpl(L){var t=FIN_TPL.pivot,k=L>=108?9/7.01:L>=94?8/7.01:1;return {B:t.B*k,D:t.D*k,sw:t.sw,r:t.r,g:t.g,foil:t.foil*Math.min(k,1.15)}}
/* side outline of a fin as a polygon: u = 0 at the leading edge of the base, toward the tail; v = depth below the board.
   Convex leading edge (steep off the base, laying back toward the tip), a round tip, and a concave trailing edge
   that rises from the back of the base and sweeps back up to the tip. */
function finProfile(t){
  var B=t.B,D=t.D,r=t.r*D,xt=B/2+D*Math.tan(t.sw*Math.PI/180),cx=xt-r*0.25,cy=D-r,pts=[];
