  var g=t.g||(t.keel?[.6,.34,.3,.1,.3]:[.58,.44,.28,.12,.3]),a0=t.keel?118:115,a1=-20,A=[cx+r*Math.cos(a0*Math.PI/180),cy+r*Math.sin(a0*Math.PI/180)],E=[cx+r*Math.cos(a1*Math.PI/180),cy+r*Math.sin(a1*Math.PI/180)];
  var tA=[Math.sin(a0*Math.PI/180),-Math.cos(a0*Math.PI/180)],tE=[Math.sin(a1*Math.PI/180),-Math.cos(a1*Math.PI/180)];
