  function add(o,t){o.tpl=t;o.len=t.B;r.push(o)}
  function side(y,inset,t){var x=Math.max(hw(y)-inset,1);add({x:x,y:y,a:-4},t);add({x:-x,y:y,a:4},t)}
  switch(c.fin){
    case 'thruster':side(L-11.5,1.25,T.perf);add({x:0,y:L-4.2,a:0},T.perf);break;
    case 'five':side(L-11.5,1.25,T.perf);add({x:0,y:L-4.2,a:0},T.perf);var x2=Math.max(hw(L-5.5)-2.6,1);add({x:x2,y:L-5.5,a:-2,box:true},T.qrear);add({x:-x2,y:L-5.5,a:2,box:true},T.qrear);break;
