    case 'twin':side(L-10.5,1.5,T.keel);break;
    case 'twinstab':side(L-10.5,1.5,T.keel);add({x:0,y:L-3.4,a:0},T.stab);break;
    case 'single':add({x:0,y:L-7.5,a:0,big:true},singleTpl(L));break;
    case 'twoplusone':add({x:0,y:L-8,a:0,big:true},singleTpl(L-6));side(L-13,1.2,T.bite);break;
  }
