function logoNode(g,c,P,lo){
  var lg=el('g',{},g),y=lo.pos.t*c.L,x=lo.pos.u*Math.max(P.hw(y)-1.4,0),col=lo.color;
  /* vertical logos read from the nose toward the tail, as on the real boards */
  var rot=lo.ori==='v'?90:0,inner=el('g',{transform:'translate('+x.toFixed(2)+' '+y.toFixed(2)+') rotate('+rot+') scale(1.55)'},lg);
  if(lo.logo==='coffin'){
    var cg=el('g',{transform:'scale(0.00456) translate(-419 -581)'},inner);
    el('path',{d:LOGO_ART.cw,fill:'#fbfaf5','fill-rule':'evenodd'},cg);
    el('path',{d:LOGO_ART.cb,fill:col,'fill-rule':'evenodd'},cg);
  }else if(lo.logo==='script'){
    var sg=el('g',{transform:'scale(0.00632) translate(-603 -230)'},inner);
    el('path',{d:LOGO_ART.sc,fill:col,stroke:'#fbfaf5','stroke-width':18,'stroke-linejoin':'round','paint-order':'stroke','fill-rule':'evenodd'},sg);
  }else if(lo.logo==='block'){
    var bg=el('g',{transform:'scale(0.0063) translate(-609 -158.5)'},inner);
    el('rect',{x:38,y:23,width:1142,height:271,rx:5,fill:col},bg);
    el('path',{d:LOGO_ART.bl,fill:'#fbfaf5','fill-rule':'evenodd'},bg);
  }else{
