/* draws a board into <g>. opts: {view:'deck'|'bottom', pts, P} */
function drawBoard(g,c,o){
  var id='b'+(++uid),view=o.view||'deck',pts=o.pts,P=o.P,L=c.L,W=c.W,d=pathD(pts);
  var defs=el('defs',{},g);
  var clip=el('clipPath',{id:id+'c'},defs);el('path',{d:d},clip);
  var blur=el('filter',{id:id+'f',x:'-50%',y:'-10%',width:'200%',height:'120%'},defs);el('feGaussianBlur',{stdDeviation:(W*.07).toFixed(2)},blur);
  var gl=el('linearGradient',{id:id+'g',x1:0,y1:0,x2:1,y2:0},defs);
  [[0,'#fff',.0],[.22,'#fff',.28],[.5,'#fff',0],[.85,'#000',.04],[1,'#000',.14]].forEach(function(s){el('stop',{offset:s[0],'stop-color':s[1],'stop-opacity':s[2]},gl)});
  var useDeck=view==='deck'||c.botSame;
