  if(useDeck){
    if(c.pat==='railfade'){el('path',{d:d,fill:'none',stroke:acc,'stroke-width':(W*.36).toFixed(2),filter:'url(#'+id+'f)'},art)}
    else if(c.pat==='dip'){
      var dg=el('linearGradient',{id:id+'d',x1:0,y1:0,x2:0,y2:1},defs);
      [[0,1],[.11,1],[.19,0],[.8,0],[.88,1],[1,1]].forEach(function(s){el('stop',{offset:s[0],'stop-color':acc,'stop-opacity':s[1]},dg)});
      el('rect',{x:-W,y:-2,width:2*W,height:L+4,fill:'url(#'+id+'d)'},art);
    }else if(c.pat==='twotone'){
      el('polygon',{points:[-W,-2,W,-2,W,L*.13,-W,L*.34].join(' '),fill:acc},art);
