  if(view==='deck'&&o.logo!==false&&c.logoD&&c.logoD.on)logoNode(art,c,P,c.logoD);
  if(view==='bottom'){
    finsFor(c,P).forEach(function(f){
      var fg=el('g',{transform:'translate('+f.x.toFixed(2)+' '+f.y.toFixed(2)+') rotate('+f.a+')'},art);
      /* seen from below a fin is a thin foil: rounded leading edge toward the nose, thickest about a third back, fine trailing edge */
      var l=f.len,h=l/2,w=Math.max(.22,(f.tpl?f.tpl.foil:.3)*(f.big?1.25:1.1));
      el('rect',{x:-w/2-.2,y:-h-.25,width:w+.4,height:l+.5,rx:.3,fill:'#2b2f33',opacity:.3},fg);
      if(!f.box)el('path',{d:'M0 '+(-h)+'C'+(w*.62)+' '+(-h)+' '+w+' '+(-h+l*.12)+' '+w+' '+(-h+l*.32)+'C'+w+' '+(-h+l*.58)+' '+(w*.32)+' '+(h-l*.06)+' '+(w*.1)+' '+h+'L'+(-w*.1)+' '+h+'C'+(-w*.32)+' '+(h-l*.06)+' '+(-w)+' '+(-h+l*.58)+' '+(-w)+' '+(-h+l*.32)+'C'+(-w)+' '+(-h+l*.12)+' '+(-w*.62)+' '+(-h)+' 0 '+(-h)+'Z',fill:c.finColor,stroke:'rgba(0,0,0,.35)','stroke-width':.05},fg);
    });
    if(o.logo!==false&&c.logoB&&c.logoB.on)logoNode(art,c,P,c.logoB);
  }
