  slides.forEach(function(b,k){
    var sr=b.getBoundingClientRect(),d=(sr.left+sr.width/2-cx)/sr.width,ad=Math.min(Math.abs(d),2.5);
    if(Math.abs(d)<bd){bd=Math.abs(d);best=k}
