    b._in.style.transform='translateY('+(ad*ad*14+lift).toFixed(1)+'px) rotate('+rot.toFixed(2)+'deg) scale('+sc.toFixed(3)+')';
    b._in.style.opacity=(1-ad*.28).toFixed(2);b._in.style.filter=ad>.5?'saturate(.6) brightness(.8)':'none';b.style.zIndex=String(10-Math.round(ad*2));
