var rafTS=0;tsTrack.addEventListener('scroll',function(){if(!rafTS)rafTS=requestAnimationFrame(function(){rafTS=0;layoutTS()})},{passive:true});
/* keep the chosen board dead-center whenever the track's width changes (scrollbar appearing, rotation, resize) */
