/* ===== back button / swipe-back: each full-screen layer gets its own history entry, so "back" closes the layer instead of leaving the page ===== */
var HIST={builder:false,nav:false,acct:false,pending:false,reopen:null,after:null,pt:0};
try{history.scrollRestoration='manual'}catch(e){}
function pushLayer(name){
  if(HIST.pending){HIST.reopen=name;return false}      /* a "back" we started has not landed yet: push after it does */
  try{
    if(name==='builder'&&location.hash==='#nav'){var had=HIST.nav;HIST.nav=false;location.replace('#builder');return had}
    if(location.hash==='#'+name)return false;
    location.hash=name;            /* moving to a new fragment always adds exactly one entry */
    return location.hash==='#'+name;
  }catch(e){return false}
}
function clearHash(name){if(location.hash==='#'+name){try{history.replaceState(null,'',location.pathname+location.search)}catch(e){}}}
function settleBack(){HIST.pending=false;clearTimeout(HIST.pt);var f=HIST.after;HIST.after=null;if(HIST.reopen){var n=HIST.reopen;HIST.reopen=null;HIST[n]=pushLayer(n)}if(f)f()}
/* close the layer now, then quietly drop its history entry */
function popLayer(name,close,after){
  var had=HIST[name]&&location.hash==='#'+name;HIST[name]=false;close();
  if(!had){clearHash(name);if(after)after();return}
  HIST.after=after||null;
  HIST.pending=true;clearTimeout(HIST.pt);HIST.pt=setTimeout(settleBack,900);
  try{history.back()}catch(e){settleBack()}
}
window.addEventListener('hashchange',function(){
  if(HIST.pending){settleBack();return}
  if(location.hash!=='#acct'&&!$('acct').hidden){HIST.acct=false;ACCT.doClose()}
  if(location.hash!=='#builder'&&location.hash!=='#acct'&&!$('custom').hidden){HIST.builder=false;doCloseCustom()}
  if(location.hash==='#builder'&&$('custom').hidden){openCustom(null);HIST.builder=true}
  if(location.hash!=='#nav'&&!$('menu').hidden){HIST.nav=false;doCloseMenu(false)}
});
function closeCustom(){popLayer('builder',doCloseCustom)}
function doCloseCustom(){
  var c=$('custom');if(c.hidden)return;if(SPRAY&&SPRAY.run)sprayStop();c.hidden=true;stop3D();stopShape(true);document.documentElement.classList.remove('cf-open');
