  var TH=window.THREE,cv=$('cf3d'),r;
  try{r=new TH.WebGLRenderer({canvas:cv,antialias:true,alpha:true,preserveDrawingBuffer:false})}catch(e){return false}
  r.setPixelRatio(Math.min(2,window.devicePixelRatio||1));r.outputEncoding=TH.sRGBEncoding;r.toneMapping=TH.NoToneMapping;
  var sc=new TH.Scene(),cam=new TH.PerspectiveCamera(26,1,1,3000);
  sc.add(new TH.HemisphereLight(0xffffff,0x8fa3ad,0.52));
  var key=new TH.DirectionalLight(0xffffff,0.62);key.position.set(-70,110,120);sc.add(key);
  var rim=new TH.DirectionalLight(0xe6f6ff,0.55);rim.position.set(120,20,-60);sc.add(rim);
  var fill=new TH.DirectionalLight(0xfff1e0,0.22);fill.position.set(80,-60,100);sc.add(fill);
  var orient=new TH.Group();sc.add(orient);var pivot=new TH.Group();orient.add(pivot);var board=new TH.Group();pivot.add(board);
  var sh=document.createElement('canvas');sh.width=sh.height=128;var sx=sh.getContext('2d'),gr=sx.createRadialGradient(64,64,0,64,64,64);gr.addColorStop(0,'rgba(13,34,48,.32)');gr.addColorStop(1,'rgba(13,34,48,0)');sx.fillStyle=gr;sx.fillRect(0,0,128,128);
  var shadow=new TH.Mesh(new TH.PlaneGeometry(1,1),new TH.MeshBasicMaterial({map:new TH.CanvasTexture(sh),transparent:true,depthWrite:false}));shadow.rotation.x=-Math.PI/2;sc.add(shadow);
  var person=new TH.Group();sc.add(person);
  var deckMat=new TH.MeshPhysicalMaterial({color:0xffffff,roughness:.42,metalness:0,clearcoat:1,clearcoatRoughness:.08,side:TH.DoubleSide,alphaTest:.5});
  var botMat=deckMat.clone();
  T3=Object.assign(T3,{ok:true,TH:TH,r:r,sc:sc,cam:cam,orient:orient,pivot:pivot,roll:ORI3==='h'?-Math.PI/2:0,board:board,shadow:shadow,person:person,deckMat:deckMat,botMat:botMat,
    yaw:-0.6,yawT:-0.55,pitch:-0.16,vel:0,drag:null,lastInt:0,raf:0,ray:new TH.Raycaster(),meshes:[]});
  /* pointer: drag rotates, a short tap places the logo on the face it hits (logo step) */
  cv.addEventListener('pointerdown',function(e){if(!e.isPrimary)return;cv.setPointerCapture(e.pointerId);T3.drag={x:e.clientX,y:e.clientY,lx:e.clientX,ly:e.clientY,t:performance.now(),moved:0,yaw:T3.yaw,pitch:T3.pitch};T3.vel=0;T3.lastInt=performance.now();cv.classList.add('dragging')});
  cv.addEventListener('pointermove',function(e){var d=T3.drag;if(!d)return;var dx=e.clientX-d.lx,dy=e.clientY-d.ly;d.moved+=Math.abs(dx)+Math.abs(dy);d.lx=e.clientX;d.ly=e.clientY;
