    T3.yaw+=dx*0.0105;T3.yawT=T3.yaw;T3.vel=dx*0.0105;T3.pitch=clamp(T3.pitch+dy*0.005,-0.5,0.3);T3.lastInt=performance.now()});
  function up(e){var d=T3.drag;if(!d)return;T3.drag=null;cv.classList.remove('dragging');T3.lastInt=performance.now();
