}
function normYaw(a){a=a%(Math.PI*2);if(a<0)a+=Math.PI*2;return a}
function sideOfYaw(a){a=normYaw(a);return (a>Math.PI/2&&a<Math.PI*1.5)?'bottom':'deck'}
function syncSideFromYaw(){
