function restAngle(v){return (v==='bottom'?Math.PI:0)+(step===3?0:(v==='bottom'?0.55:-0.55))}
function threeFace(v){if(!T3.ok)return;var base=restAngle(v),k=Math.round((T3.yaw-base)/(Math.PI*2));T3.yawT=base+k*Math.PI*2;T3.vel=0;T3.lastInt=performance.now()}
function hwScan(pts,y){var m=0;for(var i=0;i<pts.length;i++){var a=pts[i],b=pts[(i+1)%pts.length];if(a[1]===b[1])continue;if((a[1]-y)*(b[1]-y)<=0){var x=a[0]+(b[0]-a[0])*(y-a[1])/(b[1]-a[1]);if(Math.abs(x)>m)m=Math.abs(x)}}return m}
