function rocker(c,u){var rk=ROCK[c.type]||[4,1.6];return (u<0.38?rk[0]*Math.pow(1-u/0.38,2.3):0)+(u>0.72?rk[1]*Math.pow((u-0.72)/0.28,1.8):0)}
function buildBoard3D(c){
