  function geo(P,UV,I){var g=new TH.BufferGeometry();g.setAttribute('position',new TH.Float32BufferAttribute(P,3));g.setAttribute('uv',new TH.Float32BufferAttribute(UV,2));g.setIndex(I);g.computeVertexNormals();return g}
  while(T3.board.children.length){var ch=T3.board.children.pop();if(ch.geometry)ch.geometry.dispose();if(ch.material&&ch.material!==T3.deckMat&&ch.material!==T3.botMat)ch.material.dispose()}
  var dm=new TH.Mesh(geo(deckP,deckUV,idxD),T3.deckMat),bm=new TH.Mesh(geo(botP,botUV,idxB),T3.botMat);dm.userData.face='deck';bm.userData.face='bottom';
