    var cp=[],ci=[],r0=N*(M+1);for(var k=0;k<=M;k++){cp.push(deckP[(r0+k)*3],deckP[(r0+k)*3+1],deckP[(r0+k)*3+2]);cp.push(botP[(r0+k)*3],botP[(r0+k)*3+1],botP[(r0+k)*3+2])}
