    var cv=await buildSheet(),d=new Date(),stamp=d.getFullYear()+('0'+(d.getMonth()+1)).slice(-2)+('0'+d.getDate()).slice(-2),name='RIPSTIX_order_'+TYPE_BY[cfg.type].id+'_'+stamp;
    var data;
