      if(!window.jspdf){dlMsg('PDF を作れませんでした。画像（PNG）で保存してください。');return}
      var pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4',orientation:'portrait'});pdf.addImage(cv.toDataURL('image/jpeg',.92),'JPEG',0,0,210,297);
      pdf.setProperties({title:'RIPSTIX Custom Order',author:'RIPSTIX / SPLASH'});data=pdf.output('blob');name+='.pdf';
    }else{data=await new Promise(function(r){cv.toBlob(r,'image/png')});name+='.png'}
    if(dlApi)await dlApi.save({filename:name,data:data});else browserSave(name,data);dlMsg('保存しました。');
  }catch(e){
    var c=e&&e.code;dlMsg(c==='declined'?'保存をキャンセルしました。':c==='rate_limited'?'少し待ってからもう一度お試しください。':'保存できませんでした。オーダー内容をコピーしてください。');
  }
}
