  if(window.gsap&&!reduce){gsap.fromTo(menu,{opacity:0},{opacity:1,duration:.25});gsap.fromTo('#menu li',{y:40,opacity:0},{y:0,opacity:1,duration:.5,ease:'power3.out',stagger:.04});gsap.fromTo('#menu .menu-boards img',{y:60,opacity:0},{y:0,opacity:1,duration:.6,ease:'power3.out',stagger:.06,delay:.1})}
  var first=menu.querySelector('a,button');if(first)first.focus({preventScroll:true});
  HIST.nav=pushLayer('nav');
}
function closeMenu(focusBurger,after){if(menu.hidden)return;popLayer('nav',function(){doCloseMenu(focusBurger)},after)}
function doCloseMenu(focusBurger){
  if(menu.hidden)return;menu.hidden=true;document.documentElement.classList.remove('nav-open');burger.setAttribute('aria-expanded','false');burger.setAttribute('aria-label','メニューを開く');
  document.querySelectorAll('main > section:not(#custom)').forEach(function(n){n.inert=false});
