menu.addEventListener('click',function(e){
  var ac=e.target.closest('[data-acct]');if(ac){var mode=ac.getAttribute('data-acct');closeMenu(false,function(){ACCT.open(mode)});return}
  var a=e.target.closest('a[href^="#"]');var b=e.target.closest('[data-open]');
  if(b){doCloseMenu(false);return}
  if(!a)return;e.preventDefault();
  var t=document.querySelector(a.getAttribute('href'));
  /* scroll only after the menu's history entry is gone, so the history step can't interrupt it */
