    sv.setAttribute('viewBox',[-c.W/2-pad,-pad,c.W+2*pad,c.L+2*pad].join(' '));sv.setAttribute('aria-hidden','true');
    drawBoard(el('g',{},sv),c,{view:view||'deck',pts:o.pts,P:o.P});return sv}
  /* thumbnails are drawn after the HTML is in place: <div class="ac-thumb" data-th="key" data-both> */
  var THUMBS={};
  function th(c,both){var k='t'+(++uid);THUMBS[k]=c;return '<div class="ac-thumb" data-th="'+k+'"'+(both?' data-both':'')+'></div>'}
  function paintThumbs(){body.querySelectorAll('[data-th]').forEach(function(n){var c=THUMBS[n.getAttribute('data-th')];if(!c)return;
    n.appendChild(boardSvg(c,'deck'));if(n.hasAttribute('data-both'))n.appendChild(boardSvg(c,'bottom'))});THUMBS={}}
  function cleanProfile(p){p=p||{};return {name:str(p.name,60),kana:str(p.kana,60),phone:str(p.phone,20),email:str(p.email,120),zip:str(p.zip,10),addr:str(p.addr,200),
    height:num(p.height,100,230,null),weight:num(p.weight,25,200,null),level:LEVELS.indexOf(p.level)>=0?p.level:'',home:str(p.home,60),
    createdAt:num(p.createdAt,0,1e14,0),updatedAt:num(p.updatedAt,0,1e14,0),lastAt:num(p.lastAt,0,1e14,0),nBoards:num(p.nBoards,0,1e5,0),nOrders:num(p.nOrders,0,1e5,0),lastStatus:str(p.lastStatus,20)}}
  function cleanOrder(d){d=d||{};return {no:str(d.no,20),cfg:sanitize(d.cfg),status:STATUSES.indexOf(d.status)>=0||d.status==='キャンセル'?d.status:'受付',text:str(d.text,3000),
    comment:str(d.comment,1000),when:str(d.when,30),contact:str(d.contact,30),createdAt:num(d.createdAt,0,1e14,0),updatedAt:num(d.updatedAt,0,1e14,0),
    log:Array.isArray(d.log)?d.log.slice(-30).map(function(x){return {s:str(x&&x.s,20),at:num(x&&x.at,0,1e14,0)}}):[]}}
  function cleanCrm(d){d=d||{};return {kind:d.kind==='member'?'member':'walkin',uid:str(d.uid,120),name:str(d.name,60),kana:str(d.kana,60),phone:str(d.phone,20),email:str(d.email,120),addr:str(d.addr,200),
    memo:str(d.memo,4000),createdAt:num(d.createdAt,0,1e14,0),updatedAt:num(d.updatedAt,0,1e14,0),
    hist:Array.isArray(d.hist)?d.hist.slice(-200).map(function(h){h=h||{};return {id:str(h.id,30),date:str(h.date,10),item:str(h.item,120),price:str(h.price,20),status:str(h.status,20),note:str(h.note,300)}}):[]}}

  /* ---------- storage: claude.ai database, or a demo kept in this browser ---------- */
  var LSK='ripstix-demo-db';
  function lsLoad(){try{var o=JSON.parse(localStorage.getItem(LSK)||'{}');return o&&typeof o==='object'&&!Array.isArray(o)?o:{}}catch(e){return {}}}
  function lsSave(o){try{localStorage.setItem(LSK,JSON.stringify(o));return true}catch(e){return false}}
  var local={
    get:function(p){var o=lsLoad();return Promise.resolve(o[p]&&typeof o[p]==='object'?JSON.parse(JSON.stringify(o[p])):null)},
    set:function(p,d){var o=lsLoad();o[p]=JSON.parse(JSON.stringify(d));return lsSave(o)?Promise.resolve():Promise.reject({code:'quota_exceeded'})},
    update:function(p,d){var o=lsLoad();if(!o[p])return Promise.reject({code:'invalid_argument'});Object.assign(o[p],JSON.parse(JSON.stringify(d)));return lsSave(o)?Promise.resolve():Promise.reject({code:'quota_exceeded'})},
    del:function(p){var o=lsLoad();delete o[p];lsSave(o);return Promise.resolve()},
    list:function(col){var o=lsLoad(),n=col.split('/').length,out=[];Object.keys(o).forEach(function(k){var sg=k.split('/');if(sg.length===n+1&&k.indexOf(col+'/')===0)out.push({id:sg[n],data:o[k]})});return Promise.resolve(out)}
  };
  function retry(fn){return fn().catch(function(e){if(e&&e.code==='unavailable')return new Promise(function(r){setTimeout(r,400+Math.random()*600)}).then(fn);throw e})}
  var remote={
    get:function(p){return retry(function(){return S.db.doc(p).get()}).then(function(sn){return sn.exists?JSON.parse(JSON.stringify(sn.data())):null})},
    set:function(p,d){return retry(function(){return S.db.doc(p).set(d)})},
    update:function(p,d){return retry(function(){return S.db.doc(p).update(d)})},
    del:function(p){return retry(function(){return S.db.doc(p).delete()})},
    list:function(col){return retry(function(){return S.db.collection(col).limit(1000).get()}).then(function(q){return q.docs.map(function(sn){return {id:sn.id,data:JSON.parse(JSON.stringify(sn.data()))}})})}
  };
  /* on the shop's own website (e.g. Xserver): api.php beside this page keeps accounts and data in a database */
  var API='api.php',srv={csrf:''};
  function call(a,body){
    var opt={method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}};
    if(body){opt.headers['Content-Type']='application/json';opt.headers['X-CSRF']=srv.csrf;opt.body=JSON.stringify(body)}
    return fetch(API+'?a='+a,opt).then(function(r){return r.json().catch(function(){return {error:'unavailable'}}).then(function(j){
      if(j&&j.csrf)srv.csrf=j.csrf;
      if(j&&j.error==='csrf'&&body&&!opt._retry){opt._retry=true;opt.headers['X-CSRF']=srv.csrf;return fetch(API+'?a='+a,opt).then(function(r2){return r2.json()}).then(function(j2){if(j2&&j2.error)throw j2.auth?{auth:j2.auth}:{code:'unavailable'};return j2})}
      if(j&&j.auth==='login'&&/^doc_/.test(a)&&S.uid)setTimeout(sessionLost,0);   /* signed out elsewhere (e.g. password changed) */
      if(!r.ok||(j&&j.error))throw (j&&j.auth)?{auth:j.auth}:{code:(j&&j.error==='invalid_argument')?'invalid_argument':'unavailable'};
      return j})});
  }
  var server={
    get:function(p){return call('doc_get',{path:p}).then(function(j){return j.exists?j.data:null})},
    set:function(p,d){return call('doc_set',{path:p,data:d}).then(function(){})},
    update:function(p,d){return call('doc_update',{path:p,data:d}).then(function(){})},
    del:function(p){return call('doc_delete',{path:p}).then(function(){})},
    list:function(c){return call('doc_list',{col:c}).then(function(j){return j.docs||[]})}
  };
  function st(){return S.mode==='db'?remote:S.mode==='server'?server:local}
  function mine(sub){return 'members/'+S.uid+(sub?'/'+sub:'')}
  function newest(a){return a.sort(function(x,y){return (y.data.createdAt||0)-(x.data.createdAt||0)})}

  function init(){
    var done=false;
    function demo(){if(done)return;done=true;S.mode='local';S.admin=true;restore()}
    if(!(window.claude&&window.claude.use)){
      /* opened as a local file: a demo kept in this browser. On a website: use api.php, never the demo (it would open the admin screen to everyone) */
      if(location.protocol==='file:'){demo();return}
      var to=new Promise(function(res,rej){setTimeout(function(){rej({code:'timeout'})},8000)});
      Promise.race([call('me'),to]).then(function(j){done=true;S.mode='server';S.admin=!!(j.user&&j.user.admin);S.adminPending=!!(j.user&&j.user.admin_pending);
        return afterAuth(j.user?{uid:j.user.uid,email:j.user.email}:null)})
        .catch(function(){done=true;S.mode='off';S.admin=false;chrome();if(!ov.hidden)render()});
      return}
    Promise.all([window.claude.use('db'),window.claude.use('user')]).then(function(r){
      var db=r[0],u=r[1];if(!db||!u){demo();return}
      return Promise.all([u.id(),u.canEdit()]).then(function(x){
        if(!x[0]){demo();return}
        done=true;S.mode='db';S.db=db;S.cuid=x[0];S.admin=!!x[1];restore();
      });
    }).catch(demo);
  }
  function loadMine(){
    return st().get(mine()).then(function(p){
      S.profile=p?cleanProfile(p):null;
      if(!p){S.boards=[];S.orders=[];return}
      return Promise.all([st().list(mine('boards')),st().list(mine('orders'))]).then(function(r){
        S.boards=newest(r[0]).map(function(b){return {id:b.id,name:str(b.data.name,60),cfg:sanitize(b.data.cfg),createdAt:num(b.data.createdAt,0,1e14,0)}});
        S.orders=newest(r[1]).map(function(o){var c=cleanOrder(o.data);c.id=o.id;return c});
      });
    }).catch(function(e){S.loadErr=errMsg(e)}).then(function(){if(S.mode==='loading')S.mode='local';chrome();if(!ov.hidden)render()});
  }

  /* ---------- sign-in: e-mail address as the ID + password ----------
     Passwords are never stored: only a salted PBKDF2-SHA256 hash. On claude.ai the record sits in the member's
     private area (data/users/<id>/auth), which nobody else — the shop included — can read.
     Password reset sends a 6-digit code that expires in 15 minutes. This page cannot send real e-mail, so the
     message is shown on screen (marked as a demo); on the shop's own site, connect a mail-sending sign-in service
     (e.g. Firebase Authentication's sendPasswordResetEmail) at requestReset(). */
  var ITER=150000,enc=window.TextEncoder?new TextEncoder():null;
  function cryptoOk(){return !!(enc&&window.crypto&&crypto.subtle&&crypto.getRandomValues)}
  function hex(buf){return Array.prototype.map.call(new Uint8Array(buf),function(b){return ('0'+b.toString(16)).slice(-2)}).join('')}
  function sha(s){return crypto.subtle.digest('SHA-256',enc.encode(s)).then(hex)}
  function randHex(n){var a=new Uint8Array(n);crypto.getRandomValues(a);return hex(a)}
  function code6(){var a=new Uint32Array(1);crypto.getRandomValues(a);return ('00000'+(a[0]%1000000)).slice(-6)}
  function pbkdf2(pw,saltHex,iter){
    var salt=new Uint8Array(saltHex.match(/../g).map(function(h){return parseInt(h,16)}));
    return crypto.subtle.importKey('raw',enc.encode(pw),'PBKDF2',false,['deriveBits'])
      .then(function(k){return crypto.subtle.deriveBits({name:'PBKDF2',salt:salt,iterations:iter,hash:'SHA-256'},k,256)}).then(hex)}
  function same(a,b){a=String(a);b=String(b);if(a.length!==b.length)return false;var x=0;for(var i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}
  function normEmail(e){return String(e||'').normalize('NFKC').trim().toLowerCase()}
  function emailOk(e){return /^[^\s@]{1,64}@[^\s@]+\.[^\s@]{2,}$/.test(e)&&e.length<=120}
  function pwProblem(pw){if(pw.length<8)return 'パスワードは8文字以上にしてください。';if(pw.length>64)return 'パスワードは64文字以内にしてください。';
    if(!/[A-Za-z]/.test(pw)||!/\d/.test(pw))return 'パスワードには英字と数字の両方を入れてください。';return ''}
  function mask(e){var p=String(e).split('@');if(p.length<2)return e;return p[0].slice(0,2)+'***@'+p[1]}
  function AuthErr(code){return {auth:code}}
  var SES='ripstix-session';
  function sesGet(){var raw=null;try{raw=sessionStorage.getItem(SES)||localStorage.getItem(SES)}catch(e){}
    try{var s=JSON.parse(raw||'null');if(!s||typeof s!=='object'||!s.uid||!s.email||!(s.exp>Date.now()))return null;
      if(S.mode==='db'&&s.uid!==S.cuid)return null;return {uid:String(s.uid),email:normEmail(s.email)}}catch(e){return null}}
  function sesSet(s,remember){if(S.mode==='server')return;var v=JSON.stringify({uid:s.uid,email:s.email,exp:Date.now()+(remember?30:1)*864e5});
    try{sessionStorage.removeItem(SES);localStorage.removeItem(SES);(remember?localStorage:sessionStorage).setItem(SES,v)}catch(e){}}
  function sesClear(){try{sessionStorage.removeItem(SES);localStorage.removeItem(SES)}catch(e){}}
  /* where an account's record lives: on claude.ai one per viewer in their private area; in the demo, keyed by the e-mail's hash */
  function authPath(email){return S.mode==='db'?Promise.resolve('data/users/'+S.cuid+'/auth'):sha(normEmail(email)).then(function(h){return 'auth/a'+h.slice(0,40)})}
  function authRec(email){var em=normEmail(email);return authPath(em).then(function(p){return st().get(p).then(function(r){return {path:p,rec:(r&&r.email===em&&typeof r.hash==='string')?r:null,raw:r}})})}
  function demoUidForNew(){/* the demo's earlier one-device membership is carried over to the first account made here */
    try{var v=localStorage.getItem('ripstix-demo-uid'),claimed=localStorage.getItem('ripstix-demo-claimed');
      if(v&&!claimed&&/^[\w-]{4,40}$/.test(v)){localStorage.setItem('ripstix-demo-claimed','1');return v}}catch(e){}
    return 'acc-'+rid()}
  function signUp(email,pw){
    var em=normEmail(email);
    if(S.mode==='server')return call('signup',{email:em,password:pw}).then(function(j){S.admin=!!j.user.admin;S.adminPending=!!j.user.admin_pending;return {uid:j.user.uid,email:j.user.email}});
    return authRec(em).then(function(a){
      if(a.rec)throw AuthErr('exists');
      if(S.mode==='db'&&a.raw&&a.raw.email)throw AuthErr('hasOther:'+a.raw.email);
      var salt=randHex(16);
      return pbkdf2(pw,salt,ITER).then(function(h){
        var rec={email:em,uid:S.mode==='db'?S.cuid:demoUidForNew(),salt:salt,hash:h,iter:ITER,fails:0,lockUntil:0,reset:null,createdAt:Date.now(),updatedAt:Date.now()};
        return st().set(a.path,rec).then(function(){return {uid:rec.uid,email:em}});
      });
    });
  }
  function signIn(email,pw,remember){
    var em=normEmail(email);
    if(S.mode==='server')return call('login',{email:em,password:pw,remember:!!remember}).then(function(j){S.admin=!!j.user.admin;S.adminPending=!!j.user.admin_pending;return {uid:j.user.uid,email:j.user.email}});
    return authRec(em).then(function(a){
      if(!a.rec)throw AuthErr('bad');var r=a.rec,now=Date.now();
      if(r.lockUntil>now)throw AuthErr('locked');
      return pbkdf2(pw,r.salt,r.iter||ITER).then(function(h){
        if(!same(h,r.hash)){var f=(r.fails||0)+1,patch=f>=5?{fails:0,lockUntil:now+5*6e4}:{fails:f};
          return st().update(a.path,patch).catch(function(){}).then(function(){throw AuthErr(f>=5?'locked':'bad')})}
        return (r.fails||r.lockUntil?st().update(a.path,{fails:0,lockUntil:0}).catch(function(){}):Promise.resolve()).then(function(){return {uid:r.uid,email:em}});
      });
    });
  }
  function requestReset(email){
    var em=normEmail(email);
    if(S.mode==='server')return call('reset_request',{email:em}).then(function(){return {sent:true,code:null}});
    return authRec(em).then(function(a){
      if(!a.rec)return {sent:false};
      var c=code6(),now=Date.now();
      return sha(c+a.rec.salt).then(function(h){return st().update(a.path,{reset:{h:h,exp:now+15*6e4,tries:0},updatedAt:now})}).then(function(){return {sent:true,code:c}});
    });
  }
  function confirmReset(email,code,pw){
    var em=normEmail(email);
    if(S.mode==='server')return call('reset_confirm',{email:em,code:String(code),password:pw});
    return authRec(em).then(function(a){
      var r=a.rec,now=Date.now();if(!r||!r.reset||typeof r.reset!=='object')throw AuthErr('code');
      if(!(r.reset.exp>now))throw AuthErr('expired');if((r.reset.tries||0)>=5)throw AuthErr('tries');
      return sha(String(code)+r.salt).then(function(h){
        if(!same(h,r.reset.h))return st().update(a.path,{reset:{h:r.reset.h,exp:r.reset.exp,tries:(r.reset.tries||0)+1}}).catch(function(){}).then(function(){throw AuthErr('code')});
        var salt=randHex(16);
        return pbkdf2(pw,salt,ITER).then(function(nh){return st().update(a.path,{salt:salt,hash:nh,iter:ITER,reset:null,fails:0,lockUntil:0,updatedAt:now})});
      });
    });
  }
  function changePassword(cur,pw){
    if(S.mode==='server')return call('password_change',{current:cur,password:pw});
    return signIn(S.email,cur).then(function(){return authRec(S.email)}).then(function(a){
      var salt=randHex(16);return pbkdf2(pw,salt,ITER).then(function(h){return st().update(a.path,{salt:salt,hash:h,iter:ITER,reset:null,updatedAt:Date.now()})});
    });
  }
  function authMsg(e){var c=e&&e.auth;if(!c)return errMsg(e);
    if(c==='bad')return 'メールアドレスまたはパスワードが違います。';
    if(c==='rate')return '短い時間に操作が集中しています。しばらく待ってからもう一度お試しください。';
    if(c==='email')return 'メールアドレスを正しく入力してください。';
    if(c==='pw_short')return 'パスワードは8文字以上にしてください。';
    if(c==='pw_long')return 'パスワードは64文字以内にしてください。';
    if(c==='pw_mix')return 'パスワードには英字と数字の両方を入れてください。';
    if(c==='login')return 'ログインの有効期限が切れました。もう一度ログインしてください。';
    if(c==='locked')return 'ログインに5回失敗したため、5分間ロックしています。しばらく待つか、パスワードを再設定してください。';
    if(c==='exists')return 'このメールアドレスはすでに登録されています。ログインしてください。';
    if(c.indexOf('hasOther:')===0)return 'このアカウントには、すでに '+mask(c.slice(9))+' が登録されています。そのメールアドレスでログインしてください。';
    if(c==='code')return '確認コードが正しくありません。';
    if(c==='expired')return '確認コードの有効期限（15分）が切れました。もう一度コードを送信してください。';
    if(c==='tries')return '確認コードの入力に5回失敗しました。もう一度コードを送信してください。';
    return 'うまくいきませんでした。もう一度お試しください。'}
  function restore(){
    var ses=sesGet();if(!ses||!cryptoOk())return afterAuth(null);
    return authRec(ses.email).then(function(a){if(a.rec&&a.rec.uid===ses.uid)return afterAuth(ses);sesClear();return afterAuth(null)}).catch(function(){return afterAuth(null)});
  }
  function afterAuth(ses){
    S.authed=!!ses;S.email=ses?ses.email:'';S.uid=ses?ses.uid:null;
    if(!ses){S.profile=null;S.boards=[];S.orders=[];chrome();if(!ov.hidden)render();return Promise.resolve()}
    return loadMine();
  }
  /* after signing in or up: finish what the visitor was doing (save a board, place an order) */
  function continuePending(){
    var p=S.pending;
    if(!S.profile){S.view='register';render();ov.scrollTop=0;return}
    if(p&&p.kind==='board'){S.pending=null;saveBoard(p.cfg).then(function(){S.view='mypage';S.tab='boards';S.flash='ボードをマイページに保存しました。';render()}).catch(function(e){S.view='mypage';S.flash='';render()});return}
    if(p&&p.kind==='order'){S.view='order';render();ov.scrollTop=0;return}
    S.view='mypage';render();ov.scrollTop=0;
  }
  /* re-read the member's boards and orders (the shop may have moved an order forward) without disturbing a form in progress */
  var refreshing=false;
  function refreshMine(){if(refreshing)return;refreshing=true;
    Promise.all([st().list(mine('boards')),st().list(mine('orders'))]).then(function(r){
      S.boards=newest(r[0]).map(function(b){return {id:b.id,name:str(b.data.name,60),cfg:sanitize(b.data.cfg),createdAt:num(b.data.createdAt,0,1e14,0)}});
      S.orders=newest(r[1]).map(function(o){var c=cleanOrder(o.data);c.id=o.id;return c});
      if(!ov.hidden&&S.view==='mypage')render();
    }).catch(function(){}).then(function(){refreshing=false});
  }
  /* keep the member's own summary (counts, last activity) on their profile so the admin list needs one read */
  function touchProfile(extra){var p={nBoards:S.boards.length,nOrders:S.orders.length,lastAt:Date.now()};if(S.orders[0])p.lastStatus=S.orders[0].status;Object.assign(p,extra||{});
    Object.assign(S.profile,p);return st().update(mine(),p).catch(function(){})}

  /* ---------- header / menu ---------- */
  function chrome(){
    var b=$('acctBtnTx'),btn=$('acctBtn');
    if(S.authed&&S.profile){b.textContent=(S.profile.name.split(/[\s　]/)[0]||'マイページ')+' 様';btn.setAttribute('aria-label','マイページ（'+S.profile.name+' 様）')}
    else if(S.authed){b.textContent='マイページ';btn.setAttribute('aria-label','マイページ')}
    else{b.textContent='ログイン';btn.setAttribute('aria-label','ログイン・会員登録')}
    $('mAdmin').hidden=!S.admin;
  }

  /* ---------- overlay open / close (with its own history entry, like the builder) ---------- */
  var lastFocus=null;
  function open(view,opts){
    opts=opts||{};if(view==='admin'&&!S.admin)view='mypage';
    S.view=view||'mypage';if(opts.tab)S.tab=opts.tab;
    if(S.view==='admin'){S.detail=null;loadAdmin()}
    if(ov.hidden){
      lastFocus=document.activeElement;ov.hidden=false;document.documentElement.classList.add('ac-open');
      document.querySelector('main').inert=true;$('top').inert=true;
      HIST.acct=pushLayer('acct');
      if(window.gsap&&!reduce)gsap.fromTo(ov,{opacity:0,y:18},{opacity:1,y:0,duration:.3,ease:'power2.out'});
    }
    render();ov.scrollTop=0;$('acClose').focus({preventScroll:true});
    if(S.view!=='admin'&&S.mode!=='loading'&&S.authed&&S.profile)refreshMine();
  }
  function doClose(){
    if(ov.hidden)return;ov.hidden=true;document.documentElement.classList.remove('ac-open');
    document.querySelector('main').inert=false;$('top').inert=!$('custom').hidden;
    if(lastFocus&&lastFocus.focus&&document.contains(lastFocus))lastFocus.focus({preventScroll:true});
  }
  function close(after){popLayer('acct',doClose,after)}
  $('acClose').addEventListener('click',function(){close()});
  $('acctBtn').addEventListener('click',function(){open('mypage')});

  /* ---------- views ---------- */
  function setBar(title,switchHtml){$('acTitle').textContent=title;$('acSwitch').innerHTML=switchHtml||'';
    var m=$('acMode');m.hidden=S.mode!=='local';m.textContent='デモモード';m.title='このブラウザにだけ保存されるお試し版です'}
  function render(){
    THUMBS={};
    if(S.mode==='loading'){setBar('MY PAGE');body.innerHTML='<div class="ac-empty">読み込み中…</div>';return}
    if(S.mode==='off'){setBar('MY PAGE');body.innerHTML='<div class="ac-empty">ただいま会員ページをご利用いただけません。<br>お手数ですが、お電話（0470-47-4334）または Instagram の DM でお問い合わせください。</div>';return}
    var sw=S.admin?(S.view==='admin'?'<button type="button" class="btn ghost" data-go="mypage">マイページへ</button>':'<button type="button" class="btn ghost" data-go="admin">管理画面へ</button>'):'';
    if(S.view==='admin'){setBar('ADMIN',sw);renderAdmin()}
    else if(!S.authed){var av=['signup','forgot','reset'].indexOf(S.view)>=0?S.view:'login';S.view=av;
      if(av==='signup'){setBar('JOIN',sw);renderSignup()}else if(av==='forgot'||av==='reset'){setBar('PASSWORD',sw);av==='reset'?renderReset():renderForgot()}else{setBar('LOGIN',sw);renderLogin()}}
    else if(!S.profile||S.view==='register'){setBar('JOIN',sw);renderRegister()}
    else if(S.view==='password'){setBar('PASSWORD',sw);renderPassword()}
    else if(S.view==='order'){setBar('ORDER',sw);renderOrderForm()}
    else if(S.view==='ordered'){setBar('ORDER',sw);renderOrdered()}
    else{setBar('MY PAGE',sw);renderMypage()}
    paintThumbs();
  }

  /* -- register / profile form -- */
  function formHtml(p,submitLabel,isNew){
    p=p||{};
    function f(k,label,type,req,attrs,full){return '<label'+(full?' class="full"':'')+' data-f="'+k+'"><span>'+label+(req?'<i>必須</i>':'')+'</span><input name="'+k+'" type="'+type+'" value="'+esc(p[k]==null?'':p[k])+'" '+(attrs||'')+'></label>'}
    return '<form class="ac-form" id="acForm" novalidate>'+
      f('name','お名前','text',1,'autocomplete="name" maxlength="60" placeholder="例：岡田 一海"')+
      f('kana','フリガナ','text',1,'maxlength="60" placeholder="例：オカダ カズミ"')+
      f('phone','電話番号','tel',1,'autocomplete="tel" inputmode="tel" maxlength="20" placeholder="例：090-1234-5678"')+
      '<label data-f="email"><span>メールアドレス（ログインID）</span><input type="email" value="'+esc(S.email)+'" readonly aria-readonly="true" class="ac-ro"></label>'+
      f('zip','郵便番号','text',0,'autocomplete="postal-code" inputmode="numeric" maxlength="10" placeholder="例：299-2711"')+
      f('addr','住所','text',0,'autocomplete="street-address" maxlength="200" placeholder="例：千葉県南房総市和田町…"')+
      f('height','身長（cm）','number',0,'inputmode="decimal" min="100" max="230" step="0.1"')+
      f('weight','体重（kg）','number',0,'inputmode="decimal" min="25" max="200" step="0.1"')+
      '<label data-f="level"><span>サーフィン歴・レベル</span><select name="level"><option value="">選択してください</option>'+LEVELS.map(function(l){return '<option'+(p.level===l?' selected':'')+'>'+l+'</option>'}).join('')+'</select></label>'+
      f('home','よく行くポイント','text',0,'maxlength="60" placeholder="例：白渚、千倉、鴨川"')+
      '<div class="full ac-err" id="acErr" aria-live="polite"></div>'+
      '<div class="full"><button type="submit" class="btn big">'+submitLabel+'</button></div></form>';
  }
  function readForm(form,isNew){
    var g=function(k){var e=form.elements[k];return e?(e.type==='checkbox'?e.checked:String(e.value).trim()):''};
    var v={name:g('name').replace(/\s+/g,' '),kana:g('kana').replace(/\s+/g,' '),phone:g('phone'),email:S.email,zip:g('zip'),addr:g('addr'),
      height:g('height')===''?null:parseFloat(g('height')),weight:g('weight')===''?null:parseFloat(g('weight')),level:g('level'),home:g('home')};
    var bad=[];
    if(!v.name)bad.push(['name','お名前を入力してください。']);
    if(!v.kana)bad.push(['kana','フリガナを入力してください。']);
    else if(!/^[ぁ-ゖァ-ヺー\s　ー・]+$/.test(v.kana.normalize('NFKC')))bad.push(['kana','フリガナはカタカナかひらがなで入力してください。']);
    var dg=digits(v.phone);if(dg.length<10||dg.length>11)bad.push(['phone','電話番号は10〜11桁の数字で入力してください。']);
    if(v.height!=null&&!(v.height>=100&&v.height<=230))bad.push(['height','身長は100〜230cmの範囲で入力してください。']);
    if(v.weight!=null&&!(v.weight>=25&&v.weight<=200))bad.push(['weight','体重は25〜200kgの範囲で入力してください。']);
    form.querySelectorAll('[data-f]').forEach(function(n){n.classList.remove('err')});
    bad.forEach(function(b){var n=form.querySelector('[data-f="'+b[0]+'"]');if(n)n.classList.add('err')});
    $('acErr').textContent=bad.length?bad[0][1]:'';
    if(bad.length){var first=form.elements[bad[0][0]];if(first&&first.focus)first.focus()}
    v.kana=v.kana.normalize('NFKC');
    return bad.length?null:v;
  }
  function renderRegister(){
    var isNew=!S.profile;
    var lead='ボード製作のご相談に使う、お名前とご連絡先を教えてください。'+(S.pending?(S.pending.kind==='order'?'入力後、そのまま申し込み画面に進みます。':'入力後、ボードがマイページに保存されます。'):'');
    body.innerHTML=(isNew?'':'<button type="button" class="ac-back" data-go="mypage"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M10 3L5 8l5 5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>マイページに戻る</button>')+
      (isNew?'<div class="ac-stepper"><span>1. ログイン情報</span><span class="on">2. お客さま情報</span></div>':'')+'<div class="ac-hello"><div><h3>'+(isNew?'お客さま情報':'登録情報の変更')+'</h3><p>'+esc(isNew?lead:'お名前・連絡先などを変更できます。')+'</p></div></div>'+
      (S.loadErr?'<p class="ac-err">'+esc(S.loadErr)+'</p>':'')+
      '<div class="ac-card">'+formHtml(S.profile,isNew?'登録する':'変更を保存',isNew)+'</div>'+
      '<p class="ac-note">ご入力いただいた情報は、ボード製作のご相談・ご連絡・注文管理のみに利用します。</p>';
    $('acForm').addEventListener('submit',function(e){e.preventDefault();
      var v=readForm(e.target,isNew);if(!v)return;var btn=e.target.querySelector('[type=submit]');btn.disabled=true;
      var now=Date.now(),data=Object.assign({},S.profile||{},v,{updatedAt:now});
      if(isNew)Object.assign(data,{createdAt:now,lastAt:now,nBoards:0,nOrders:0,lastStatus:''});
      st().set(mine(),data).then(function(){
        S.profile=cleanProfile(data);chrome();
        if(isNew){if(!S.pending)S.flash='会員登録が完了しました。';continuePending();return}
        S.view='mypage';S.tab='profile';S.flash='登録情報を保存しました。';render();
      }).catch(function(err){btn.disabled=false;$('acErr').textContent=errMsg(err)});
    });
  }


  /* -- sign-in screens -- */
  var BACKSVG='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M10 3L5 8l5 5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
  function pwField(name,label,ac,hint){return '<label class="full" data-f="'+name+'"><span>'+label+'<i>必須</i></span><span class="ac-pw"><input name="'+name+'" type="password" autocomplete="'+ac+'" maxlength="64" spellcheck="false" autocapitalize="off"><button type="button" class="ac-eye" data-eye aria-pressed="false" aria-label="パスワードを表示">表示</button></span>'+(hint?'<small class="ac-hint">'+hint+'</small>':'')+'</label>'}
  function emailField(v,ac){return '<label class="full" data-f="email"><span>メールアドレス（ログインID）<i>必須</i></span><input name="email" type="email" autocomplete="'+(ac||'username')+'" inputmode="email" maxlength="120" spellcheck="false" autocapitalize="off" value="'+esc(v||'')+'" placeholder="例：name@example.com"></label>'}
  function flash(){var f=S.flash;S.flash='';return f?'<div class="ac-flash" role="status">'+esc(f)+'</div>':''}
  function noCrypto(){return cryptoOk()?'':'<p class="ac-err">このブラウザでは、安全なログインに必要な機能が使えません。最新のブラウザでお試しください。</p>'}
  function fieldErr(form,key,msg){form.querySelectorAll('[data-f]').forEach(function(n){n.classList.remove('err')});
    if(key){var n=form.querySelector('[data-f="'+key+'"]');if(n)n.classList.add('err');var i=form.elements[key];if(i&&i.focus)i.focus()}
    form.querySelector('.ac-err').textContent=msg||''}
  function busy(form,on,label){var b=form.querySelector('[type=submit]');b.disabled=on;if(on){b.dataset.t=b.textContent;b.textContent=label||'処理中…'}else if(b.dataset.t)b.textContent=b.dataset.t}
  function pendingLead(){return S.pending?(S.pending.kind==='order'?'オーダーのお申し込みには、ログイン（会員登録）が必要です。':'ボードを保存するには、ログイン（会員登録）が必要です。'):''}
  function renderLogin(){
    body.innerHTML='<div class="ac-auth">'+flash()+'<div class="ac-hello"><div><h3>ログイン</h3><p>'+esc(pendingLead()||'ご登録のメールアドレスとパスワードを入力してください。')+'</p></div></div>'+noCrypto()+
      '<div class="ac-card"><form class="ac-form" id="acLogin" novalidate>'+emailField(S.loginEmail,'username')+pwField('password','パスワード','current-password')+
      '<label class="chk full"><input type="checkbox" name="remember" checked><span>ログインしたままにする（30日間）</span></label>'+
      '<div class="full ac-err" aria-live="polite"></div><div class="full"><button type="submit" class="btn big">ログイン</button></div>'+
      '<div class="full"><button type="button" class="ac-link" data-go="forgot">パスワードをお忘れの方</button></div></form></div>'+
      '<div class="ac-card ac-join"><div><b>はじめての方</b><p>会員登録（無料）で、組んだボードの保存、オーダーの申し込み、進み具合の確認ができます。</p></div><button type="button" class="btn ghost" data-go="signup">会員登録する</button></div></div>';
    $('acLogin').addEventListener('submit',function(e){e.preventDefault();var f=e.target,em=normEmail(f.elements.email.value),pw=f.elements.password.value;
      if(!emailOk(em))return fieldErr(f,'email','メールアドレスを正しく入力してください。');
      if(!pw)return fieldErr(f,'password','パスワードを入力してください。');
      if(!cryptoOk())return;fieldErr(f,null,'');busy(f,true,'確認しています…');S.loginEmail=em;
      signIn(em,pw,f.elements.remember.checked).then(function(s){sesSet(s,f.elements.remember.checked);return afterAuth(s)}).then(continuePending)
        .catch(function(err){busy(f,false);fieldErr(f,'password',authMsg(err));f.elements.password.value=''});
    });
  }
  function renderSignup(){
    body.innerHTML='<div class="ac-auth"><button type="button" class="ac-back" data-go="login">'+BACKSVG+'ログイン画面に戻る</button>'+
      '<div class="ac-stepper"><span class="on">1. ログイン情報</span><span>2. お客さま情報</span></div>'+
      '<div class="ac-hello"><div><h3>会員登録</h3><p>'+esc(pendingLead()||'メールアドレスがログインIDになります。')+'</p></div></div>'+noCrypto()+
      '<div class="ac-card"><form class="ac-form" id="acSignup" novalidate>'+emailField(S.loginEmail,'email')+
      pwField('password','パスワード','new-password','8文字以上・英字と数字をどちらも含めてください')+pwField('password2','パスワード（確認）','new-password')+
      '<label class="chk full" data-f="agree"><input type="checkbox" name="agree"><span>入力した情報を、RIPSTIX（株式会社LTR）がボード製作のご相談・ご連絡・注文管理のために利用することに同意します（<a href="privacy.html" target="_blank" rel="noopener">プライバシーポリシー</a>）。</span></label>'+
      '<div class="full ac-err" aria-live="polite"></div><div class="full"><button type="submit" class="btn big">次へ（お客さま情報の入力）</button></div></form></div></div>';
    $('acSignup').addEventListener('submit',function(e){e.preventDefault();var f=e.target,em=normEmail(f.elements.email.value),pw=f.elements.password.value,pw2=f.elements.password2.value;
      if(!emailOk(em))return fieldErr(f,'email','メールアドレスを正しく入力してください。');
      var bad=pwProblem(pw);if(bad)return fieldErr(f,'password',bad);
      if(pw!==pw2)return fieldErr(f,'password2','確認用のパスワードが一致しません。');
      if(!f.elements.agree.checked)return fieldErr(f,'agree','個人情報の取り扱いへの同意が必要です。');
      if(!cryptoOk())return;fieldErr(f,null,'');busy(f,true,'登録しています…');S.loginEmail=em;
      signUp(em,pw).then(function(s){sesSet(s,true);return afterAuth(s)}).then(continuePending)
        .catch(function(err){busy(f,false);fieldErr(f,err&&err.auth==='exists'?'email':null,authMsg(err))});
    });
  }
  function renderForgot(){
    body.innerHTML='<div class="ac-auth"><button type="button" class="ac-back" data-go="login">'+BACKSVG+'ログイン画面に戻る</button>'+
      '<div class="ac-hello"><div><h3>パスワードの再設定</h3><p>ご登録のメールアドレスに、6桁の確認コードをお送りします。</p></div></div>'+noCrypto()+
      '<div class="ac-card"><form class="ac-form" id="acForgot" novalidate>'+emailField(S.loginEmail,'username')+
      '<div class="full ac-err" aria-live="polite"></div><div class="full"><button type="submit" class="btn big">確認コードを送る</button></div></form></div></div>';
    $('acForgot').addEventListener('submit',function(e){e.preventDefault();var f=e.target,em=normEmail(f.elements.email.value);
      if(!emailOk(em))return fieldErr(f,'email','メールアドレスを正しく入力してください。');
      if(!cryptoOk())return;busy(f,true,'送信しています…');sendCode(em).catch(function(err){busy(f,false);fieldErr(f,null,authMsg(err))});
    });
  }
  function sendCode(em){
    return requestReset(em).then(function(r){S.loginEmail=em;S.resetEmail=em;S.sentAt=Date.now();S.mail=r.sent&&r.code?{to:em,code:r.code}:null;S.view='reset';render();ov.scrollTop=0});
  }
  function renderReset(){
    var m=S.mail,wait=Math.max(0,30-Math.round((Date.now()-(S.sentAt||0))/1000));
    body.innerHTML='<div class="ac-auth"><button type="button" class="ac-back" data-go="forgot">'+BACKSVG+'メールアドレスを入力し直す</button>'+flash()+
      '<div class="ac-hello"><div><h3>新しいパスワードの設定</h3><p>'+esc(S.resetEmail)+' 宛てに確認コードを送信しました。ご登録がない場合はメールは届きません。コードの有効期限は15分です。</p></div></div>'+
      (m?'<div class="ac-mail" role="note"><div class="ac-mail-tag">デモ表示：本番では、この内容がメールで届きます</div>'+
        '<div class="ac-mail-h"><b>件名</b>【RIPSTIX】パスワード再設定の確認コード<br><b>宛先</b>'+esc(m.to)+'</div>'+
        '<p>RIPSTIX をご利用いただきありがとうございます。<br>パスワード再設定の確認コードは次のとおりです。</p><div class="code">'+esc(m.code)+'</div><p class="ac-note">このコードは15分間有効です。お心当たりのない場合は、このメールを破棄してください。</p></div>':'')+
      '<div class="ac-card"><form class="ac-form" id="acReset" novalidate>'+
      '<label class="full" data-f="code"><span>確認コード（6桁）<i>必須</i></span><input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]*" placeholder="000000" class="ac-codein"></label>'+
      pwField('password','新しいパスワード','new-password','8文字以上・英字と数字をどちらも含めてください')+pwField('password2','新しいパスワード（確認）','new-password')+
      '<div class="full ac-err" aria-live="polite"></div><div class="full"><button type="submit" class="btn big">パスワードを再設定する</button></div>'+
      '<div class="full"><button type="button" class="ac-link" data-act="resend"'+(wait?' disabled':'')+'>'+(wait?'コードを再送する（'+wait+'秒後）':'コードを再送する')+'</button></div></form></div></div>';
    if(wait){clearTimeout(S.wt);S.wt=setTimeout(function(){var b=body.querySelector('[data-act=resend]');if(b&&S.view==='reset'){b.disabled=false;b.textContent='コードを再送する'}},wait*1000)}
    $('acReset').addEventListener('submit',function(e){e.preventDefault();var f=e.target,code=digits(f.elements.code.value),pw=f.elements.password.value,pw2=f.elements.password2.value;
      if(code.length!==6)return fieldErr(f,'code','6桁の確認コードを入力してください。');
      var bad=pwProblem(pw);if(bad)return fieldErr(f,'password',bad);
      if(pw!==pw2)return fieldErr(f,'password2','確認用のパスワードが一致しません。');
      if(!cryptoOk())return;busy(f,true,'設定しています…');
      confirmReset(S.resetEmail,code,pw).then(function(){S.mail=null;S.loginEmail=S.resetEmail;S.flash='パスワードを再設定しました。新しいパスワードでログインしてください。';S.view='login';render();ov.scrollTop=0})
        .catch(function(err){busy(f,false);fieldErr(f,'code',authMsg(err))});
    });
  }
  function renderPassword(){
    body.innerHTML='<div class="ac-auth"><button type="button" class="ac-back" data-go="mypage">'+BACKSVG+'マイページに戻る</button>'+
      '<div class="ac-hello"><div><h3>パスワードの変更</h3><p>ログインID：'+esc(S.email)+'</p></div></div>'+
      '<div class="ac-card"><form class="ac-form" id="acPw" novalidate><input type="email" name="username" autocomplete="username" value="'+esc(S.email)+'" hidden>'+
      pwField('current','いまのパスワード','current-password')+pwField('password','新しいパスワード','new-password','8文字以上・英字と数字をどちらも含めてください')+pwField('password2','新しいパスワード（確認）','new-password')+
      '<div class="full ac-err" aria-live="polite"></div><div class="full"><button type="submit" class="btn big">変更する</button></div>'+
      '<div class="full"><button type="button" class="ac-link" data-act="forgotIn">いまのパスワードがわからない場合</button></div></form></div></div>';
    $('acPw').addEventListener('submit',function(e){e.preventDefault();var f=e.target,cur=f.elements.current.value,pw=f.elements.password.value,pw2=f.elements.password2.value;
      if(!cur)return fieldErr(f,'current','いまのパスワードを入力してください。');
      var bad=pwProblem(pw);if(bad)return fieldErr(f,'password',bad);
      if(pw!==pw2)return fieldErr(f,'password2','確認用のパスワードが一致しません。');
      if(pw===cur)return fieldErr(f,'password','いまと違うパスワードにしてください。');
      busy(f,true,'変更しています…');
      changePassword(cur,pw).then(function(){S.flash='パスワードを変更しました。';S.view='mypage';S.tab='profile';render();ov.scrollTop=0})
        .catch(function(err){busy(f,false);fieldErr(f,'current',err&&err.auth==='bad'?'いまのパスワードが違います。':authMsg(err))});
    });
  }
  function sessionLost(){if(!S.uid)return;sesClear();S.pending=null;S.view='login';S.admin=false;S.adminPending=false;
    afterAuth(null).then(function(){S.flash='ログインの有効期限が切れたか、別の端末でパスワードが変更されました。もう一度ログインしてください。';render();ov.scrollTop=0})}
  function signOut(){sesClear();S.pending=null;S.view='login';(S.mode==='server'?call('logout',{}).catch(function(){}):Promise.resolve()).then(function(){if(S.mode==='server'){S.admin=false;S.adminPending=false}return afterAuth(null)}).then(function(){S.flash='ログアウトしました。';render();ov.scrollTop=0})}

  /* -- my page -- */
  function stepsHtml(status){
    if(status==='キャンセル')return '<span class="ac-cancel">キャンセル</span>';
    var k=STATUSES.indexOf(status);
    return '<div class="ac-steps" aria-label="進み具合：'+esc(status)+'">'+STATUSES.map(function(x,i){return '<span class="'+(i<k?'done':i===k?'now':'')+'">'+x+'</span>'}).join('')+'</div>';
  }
  function renderMypage(){
    var p=S.profile,tabs=[['boards','保存したボード',S.boards.length],['orders','注文履歴',S.orders.length],['profile','登録情報','']];
    var h=flash()+'<div class="ac-hello"><div><h3>'+esc(p.name)+' 様</h3><p>ログインID '+esc(S.email)+'　·　会員登録日 '+d8(p.createdAt)+'</p></div><div class="ac-acts" style="margin:0"><button type="button" class="btn" data-act="build">新しいボードを組む</button><button type="button" class="btn ghost" data-act="logout">ログアウト</button></div></div>'+
      (S.mode==='server'&&S.adminPending?'<div class="ac-card ac-verify"><h4>管理者の確認</h4><p class="ac-meta">このメールアドレスは管理者として登録されています。'+esc(S.email)+' に届いた6桁の確認コードを入力すると、管理画面が使えるようになります。</p>'+
        '<form id="acVerify" class="ac-mini" style="margin:0" novalidate><label>確認コード<input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456"></label><div class="ac-acts" style="margin:0"><button type="submit" class="btn">確認する</button><button type="button" class="btn ghost" data-act="vresend">コードを再送する</button></div><div class="ac-err" id="acVErr" aria-live="polite"></div></form></div>':'')+
      '<div class="ac-tabs" role="tablist">'+tabs.map(function(t){return '<button type="button" role="tab" data-tab="'+t[0]+'" aria-selected="'+(S.tab===t[0])+'">'+t[1]+(t[2]!==''?'<b>'+t[2]+'</b>':'')+'</button>'}).join('')+'</div>';
    if(S.tab==='boards'){
      h+=S.boards.length?'<div class="ac-grid">'+S.boards.map(function(b,i){return '<div class="ac-card ac-board">'+th(b.cfg)+'<div><h4>'+esc(b.name||TYPE_BY[b.cfg.type].en)+'</h4><div class="ac-meta">'+esc(spec(b.cfg))+'<br>保存日 '+d8(b.createdAt)+'</div>'+
        '<div class="ac-acts"><button type="button" class="btn" data-act="edit" data-i="'+i+'">カスタムで開く</button><button type="button" class="btn ghost" data-act="orderb" data-i="'+i+'">注文する</button><button type="button" class="btn danger" data-act="delb" data-i="'+i+'">削除</button></div></div></div>'}).join('')+'</div>'
        :'<div class="ac-empty">まだ保存したボードはありません。<br>カスタム画面の最後の「マイボードに保存」で、ここに残せます。<br><button type="button" class="btn" data-act="build">ボードを組む</button></div>';
    }else if(S.tab==='orders'){
      h+=S.orders.length?S.orders.map(function(o){return '<div class="ac-card ac-order">'+th(o.cfg)+'<div><div class="ac-no">'+esc(o.no)+'</div><div class="ac-meta">申込日 '+d8(o.createdAt)+'　·　'+esc(spec(o.cfg))+'</div>'+stepsHtml(o.status)+
        (o.comment?'<p class="ac-note">ご要望：'+esc(o.comment)+'</p>':'')+'</div></div>'}).join('')+
        '<p class="ac-note">進み具合はお店で更新されます。価格・納期は、内容を確認のうえお店からご案内します。</p>'
        :'<div class="ac-empty">まだ注文はありません。<br>保存したボード、またはカスタム画面からお申し込みいただけます。</div>';
    }else{
      h+='<div class="ac-card"><dl class="ac-dl">'+[['お名前',p.name],['フリガナ',p.kana],['電話番号',p.phone],['メール（ログインID）',S.email],['郵便番号',p.zip],['住所',p.addr],['身長',p.height?p.height+' cm':''],['体重',p.weight?p.weight+' kg':''],['レベル',p.level],['よく行くポイント',p.home]].map(function(r){return '<dt>'+r[0]+'</dt><dd>'+(r[1]?esc(r[1]):'<span style="color:var(--ink-soft)">未入力</span>')+'</dd>'}).join('')+'</dl>'+
        '<div class="ac-acts"><button type="button" class="btn ghost" data-go="register">登録情報を変更する</button><button type="button" class="btn ghost" data-go="password">パスワードを変更する</button></div></div>';
    }
    body.innerHTML=h;
    var vf=$('acVerify');
    if(vf){vf.addEventListener('submit',function(e){e.preventDefault();var code=String(vf.elements.code.value).replace(/\D/g,'');
        if(code.length!==6){$('acVErr').textContent='メールに届いた6桁の数字を入力してください。';return}
        var b=vf.querySelector('[type=submit]');b.disabled=true;
        call('verify_confirm',{code:code}).then(function(j){S.admin=!!j.user.admin;S.adminPending=!!j.user.admin_pending;chrome();S.flash='管理者として確認できました。メニューの「ADMIN」から管理画面を使えます。';render()})
          .catch(function(err){b.disabled=false;var a=err&&err.auth;$('acVErr').textContent=a==='expired'?'確認コードの有効期限が切れました。「コードを再送する」を押してください。':a==='tries'?'入力ミスが多すぎます。「コードを再送する」で新しいコードを受け取ってください。':a==='rate'?'操作が多すぎます。しばらく待ってからお試しください。':'確認コードが正しくありません。'})});
      vf.querySelector('[data-act=vresend]').addEventListener('click',function(e){var b=e.currentTarget;b.disabled=true;
        call('verify_send',{}).then(function(){$('acVErr').textContent='確認コードを送りました。メールをご確認ください。'}).catch(function(err){$('acVErr').textContent=err&&err.auth==='wait'?'30秒ほど待ってから、もう一度お試しください。':'送信できませんでした。しばらく待ってからお試しください。'}).then(function(){setTimeout(function(){b.disabled=false},3000)})})}
  }
  function saveBoard(c){
    var id=rid(),t=TYPE_BY[c.type],data={name:t.en+' '+ftIn(c.L),cfg:c,createdAt:Date.now()};
    return st().set(mine('boards/'+id),data).then(function(){S.boards.unshift({id:id,name:data.name,cfg:c,createdAt:data.createdAt});return touchProfile()});
  }

  /* -- order form / done -- */
  function renderOrderForm(){
    var c=S.pending&&S.pending.cfg;if(!c){S.view='mypage';renderMypage();return}
    body.innerHTML='<button type="button" class="ac-back" data-act="cancelOrder"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M10 3L5 8l5 5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>戻る</button>'+
      '<div class="ac-hello"><div><h3>オーダーのお申し込み</h3><p>この内容でお店に申し込みます。価格・納期は、内容を確認のうえお店からご案内します。</p></div></div>'+
      '<div class="ac-card ac-sum">'+th(c,true)+'<pre class="ac-pre">'+esc(textFor(c).split('\n').slice(1,13).join('\n'))+'</pre></div>'+
      '<div class="ac-card" style="margin-top:14px"><form class="ac-form" id="acOrder" novalidate>'+
      '<label data-f="when">ご希望の時期<select name="when"><option>できるだけ早く</option><option>1ヶ月以内</option><option>2〜3ヶ月以内</option><option>時期は未定</option></select></label>'+
      '<label data-f="contact">ご希望の連絡方法<select name="contact"><option>電話</option><option>メール</option><option>Instagram の DM</option><option>店頭で相談</option></select></label>'+
      '<label class="full" data-f="comment">ご要望・ご質問（任意）<textarea name="comment" maxlength="1000" placeholder="例：冬の腰〜胸の波でも乗りやすくしたい。ロゴを少し小さめに。"></textarea></label>'+
      '<div class="full notice" role="note"><b class="nt">ご注文前にご確認ください</b><p>※ フィンおよびストリンガーの色は、製造工程の都合上、ご希望どおりにお作りできない場合がございます。</p><p>※ カラー・デザインは、気温・湿度・塗りの回数・クロスの質によって仕上がりが大きく変わります。まったく同じデザインにはならないことを、あらかじめご了承ください。</p></div>'+
      '<label class="chk full" data-f="agree"><input type="checkbox" name="agree"><span>上記の注意事項を確認し、了承しました。</span></label>'+
      '<div class="full ac-err" id="acErr" aria-live="polite"></div><div class="full"><button type="submit" class="btn big">申し込む</button></div></form></div>';
    $('acOrder').addEventListener('submit',function(e){e.preventDefault();var f=e.target;
      f.querySelectorAll('[data-f]').forEach(function(n){n.classList.remove('err')});
      if(!f.elements.agree.checked){f.querySelector('[data-f="agree"]').classList.add('err');$('acErr').textContent='注意事項の確認にチェックを入れてください。';return}
      var btn=f.querySelector('[type=submit]');btn.disabled=true;
      var now=Date.now(),id=rid(),o={no:orderNo(),cfg:c,status:'受付',text:textFor(c),comment:String(f.elements.comment.value).trim().slice(0,1000),
        when:f.elements.when.value,contact:f.elements.contact.value,createdAt:now,updatedAt:now,log:[{s:'受付',at:now}]};
      st().set(mine('orders/'+id),o).then(function(){o.id=id;S.orders.unshift(cleanOrder(o));S.orders[0].id=id;S.last=o;S.pending=null;return touchProfile({lastStatus:'受付'})})
        .then(function(){S.view='ordered';render()}).catch(function(err){btn.disabled=false;$('acErr').textContent=errMsg(err)});
    });
  }
  function renderOrdered(){
    var o=S.last||{};
    body.innerHTML='<div class="ac-card ac-done"><div class="eyebrow" style="color:var(--ink-soft)">THANK YOU</div><h3 style="margin:6px 0 0">お申し込みを受け付けました</h3><b>'+esc(o.no)+'</b>'+
      '<p>内容を確認のうえ、ご希望の方法（'+esc(o.contact||'')+'）でお店からご連絡いたします。<br>進み具合はマイページの「注文履歴」でご確認いただけます。</p>'+
      '<div class="ac-acts" style="justify-content:center"><button type="button" class="btn" data-act="toOrders">注文履歴を見る</button><button type="button" class="btn ghost" data-act="closeAll">閉じる</button></div></div>';
  }

  /* -- admin: customer list with name search -- */
  function loadAdmin(){
    if(!S.admin)return;S.list=null;
    Promise.all([st().list('members'),st().list('crm')]).then(function(r){
      var crm={};r[1].forEach(function(x){crm[x.id]=cleanCrm(x.data)});
      var rows=r[0].map(function(m){var p=cleanProfile(m.data),c=crm['m_'+m.id];
        return {key:'m:'+m.id,kind:'member',uid:m.id,p:p,crm:c||null,name:p.name,kana:p.kana,phone:p.phone,email:p.email,boards:p.nBoards,orders:p.nOrders+(c?c.hist.length:0),status:p.lastStatus,at:Math.max(p.lastAt||0,p.updatedAt||0,c?c.updatedAt:0)}});
      Object.keys(crm).forEach(function(k){var c=crm[k];if(c.kind!=='walkin')return;
        rows.push({key:'w:'+k,kind:'walkin',cid:k,crm:c,name:c.name,kana:c.kana,phone:c.phone,email:c.email,boards:0,orders:c.hist.length,status:c.hist.length?c.hist[c.hist.length-1].status:'',at:c.updatedAt||c.createdAt})});
      rows.sort(function(a,b){return (b.at||0)-(a.at||0)});
      S.list=rows;if(S.view==='admin'&&!S.detail)render();
    }).catch(function(e){S.list=[];S.adminErr=errMsg(e);if(S.view==='admin')render()});
  }
  function hl(text,q){text=String(text||'');if(!q)return esc(text);
    /* highlight on the normalised form; map back by scanning character positions */
    var nt='',map=[];for(var i=0;i<text.length;i++){var n=norm(text[i]);for(var j=0;j<n.length;j++){nt+=n[j];map.push(i)}}
    var k=nt.indexOf(q);if(k<0)return esc(text);var a=map[k],b=map[k+q.length-1]+1;
    return esc(text.slice(0,a))+'<mark>'+esc(text.slice(a,b))+'</mark>'+esc(text.slice(b))}
  function filtered(){
    var q=norm(S.q),qd=digits(S.q);
    return (S.list||[]).filter(function(r){
      if(S.filter!=='all'&&r.kind!==S.filter)return false;if(!q)return true;
      return norm(r.name).indexOf(q)>=0||norm(r.kana).indexOf(q)>=0||(qd.length>=3&&digits(r.phone).indexOf(qd)>=0)||norm(r.email).indexOf(q)>=0;
    });
  }
  function renderAdmin(){
    if(S.detail){renderDetail();return}
    var h='<div class="ac-hello"><div><h3>顧客管理</h3><p>会員登録したお客さまと、店頭で登録したお客さまをまとめて検索できます。</p></div>'+
      '<div class="ac-acts" style="margin:0"><button type="button" class="btn" data-act="newWalkin">店頭のお客さまを追加</button><button type="button" class="btn ghost" data-act="csv">CSVで書き出す</button></div></div>'+
      '<div class="ac-search"><div class="q"><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M13 13l4.5 4.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>'+
      '<input type="search" id="acQ" placeholder="名前・フリガナ・電話番号で検索" value="'+esc(S.q)+'" aria-label="顧客を検索" autocomplete="off"></div>'+
      '<div class="ac-seg" role="group" aria-label="種別">'+[['all','すべて'],['member','会員'],['walkin','店頭']].map(function(x){return '<button type="button" data-filter="'+x[0]+'" aria-pressed="'+(S.filter===x[0])+'">'+x[1]+'</button>'}).join('')+'</div>'+
      '<button type="button" class="btn ghost" data-act="reload" style="min-height:44px">更新</button></div>'+
      '<div id="acList"></div>';
    body.innerHTML=h;listOnly();
    var qi=$('acQ');qi.addEventListener('input',function(){S.q=qi.value;listOnly()});
  }
  function listOnly(){
    var box=$('acList');if(!box)return;
    if(S.adminErr){box.innerHTML='<p class="ac-err">'+esc(S.adminErr)+'</p>';S.adminErr='';return}
    if(!S.list){box.innerHTML='<div class="ac-empty">読み込み中…</div>';return}
    var rows=filtered(),q=norm(S.q),all=S.list;
    var stats='<div class="ac-stats"><span><b>'+all.length+'</b>件の顧客</span><span><b>'+all.filter(function(r){return r.kind==='member'}).length+'</b>会員</span><span><b>'+all.filter(function(r){return r.kind==='walkin'}).length+'</b>店頭</span>'+(q?'<span>検索結果 <b>'+rows.length+'</b>件</span>':'')+'</div>';
    if(!all.length){box.innerHTML=stats+'<div class="ac-empty">まだ顧客データはありません。<br>会員登録があるとここに表示されます。店頭のお客さまは「店頭のお客さまを追加」から登録できます。</div>';return}
    if(!rows.length){box.innerHTML=stats+'<div class="ac-empty">「'+esc(S.q)+'」に一致するお客さまは見つかりませんでした。</div>';return}
    box.innerHTML=stats+'<table class="ac-table"><thead><tr><th>お名前</th><th>種別</th><th>電話番号</th><th>ボード / 注文</th><th>最新の状況</th><th>最終更新</th></tr></thead><tbody>'+
      rows.map(function(r){return '<tr tabindex="0" data-key="'+esc(r.key)+'"><td class="nm"><b>'+hl(r.name||'（名前なし）',q)+'</b><small>'+hl(r.kana,q)+'</small></td>'+
        '<td><span class="ac-kind'+(r.kind==='walkin'?' w':'')+'">'+(r.kind==='member'?'会員':'店頭')+'</span></td><td class="mono">'+esc(r.phone||'—')+'</td>'+
        '<td class="mono hide-sm">'+r.boards+' / '+r.orders+'</td><td class="hide-sm">'+esc(r.status||'—')+'</td><td class="mono hide-sm">'+d8(r.at)+'</td></tr>'}).join('')+'</tbody></table>';
  }
  function openDetail(key){
    var r=(S.list||[]).filter(function(x){return x.key===key})[0];if(!r)return;
    S.detail={key:key,row:r,boards:null,orders:null};render();ov.scrollTop=0;
    if(r.kind==='member'){
      Promise.all([st().list('members/'+r.uid+'/boards'),st().list('members/'+r.uid+'/orders')]).then(function(x){
        if(!S.detail||S.detail.key!==key)return;
        S.detail.boards=newest(x[0]).map(function(b){return {id:b.id,name:str(b.data.name,60),cfg:sanitize(b.data.cfg),createdAt:num(b.data.createdAt,0,1e14,0)}});
        S.detail.orders=newest(x[1]).map(function(o){var c=cleanOrder(o.data);c.id=o.id;return c});render();
      }).catch(function(e){if(S.detail){S.detail.err=errMsg(e);S.detail.boards=[];S.detail.orders=[];render()}});
    }
  }
  function crmKey(r){return r.kind==='member'?'m_'+r.uid:r.cid}
  function crmOf(r){return r.crm||cleanCrm({kind:r.kind,uid:r.uid||'',name:r.name,kana:r.kana,phone:r.phone,email:r.email,createdAt:Date.now()})}
  function saveCrm(r,c){c.updatedAt=Date.now();return st().set('crm/'+crmKey(r),c).then(function(){r.crm=c;r.at=Math.max(r.at||0,c.updatedAt);if(r.kind==='walkin'){r.name=c.name;r.kana=c.kana;r.phone=c.phone;r.email=c.email;r.orders=c.hist.length;r.status=c.hist.length?c.hist[c.hist.length-1].status:''}})}
  function renderDetail(){
    var d=S.detail,r=d.row,c=crmOf(r),p=r.p||{};
    var back='<button type="button" class="ac-back" data-act="backList"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M10 3L5 8l5 5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>顧客一覧に戻る</button>';
    var info;
    if(r.kind==='member'){
      info='<dl class="ac-dl">'+[['フリガナ',p.kana],['電話番号',p.phone],['メール',p.email],['郵便番号',p.zip],['住所',p.addr],['身長 / 体重',(p.height?p.height+' cm':'—')+' / '+(p.weight?p.weight+' kg':'—')],['レベル',p.level],['ポイント',p.home],['会員登録日',d8(p.createdAt)]].map(function(x){return '<dt>'+x[0]+'</dt><dd>'+esc(x[1]||'—')+'</dd>'}).join('')+'</dl>'+
        '<p class="ac-note">登録情報はお客さま本人がマイページで変更します。</p>';
    }else{
      info='<form class="ac-mini" id="acWalk">'+[['name','お名前'],['kana','フリガナ'],['phone','電話番号'],['email','メール']].map(function(x){return '<label style="display:grid;gap:4px;font-size:12px;font-weight:700;color:var(--ink-soft)">'+x[1]+'<input name="'+x[0]+'" value="'+esc(c[x[0]])+'" maxlength="120"></label>'}).join('')+
        '<label class="full" style="display:grid;gap:4px;font-size:12px;font-weight:700;color:var(--ink-soft)">住所<input name="addr" value="'+esc(c.addr)+'" maxlength="200"></label>'+
        '<div class="full ac-acts" style="margin-top:2px"><button type="submit" class="btn">基本情報を保存</button><button type="button" class="btn danger" data-act="delWalk">この顧客を削除</button></div><div class="full ac-ok" id="acWalkMsg" aria-live="polite"></div></form>';
    }
    var webOrders='';
    if(r.kind==='member'){
      if(!d.orders)webOrders='<div class="ac-empty">読み込み中…</div>';
      else if(!d.orders.length)webOrders='<p class="ac-note">Webからの注文はまだありません。</p>';
      else webOrders=d.orders.map(function(o,i){return '<div class="ac-card ac-order" style="padding:14px">'+th(o.cfg)+'<div><div class="ac-no">'+esc(o.no)+'</div><div class="ac-meta">申込 '+d8(o.createdAt)+' · '+esc(spec(o.cfg))+'<br>希望時期：'+esc(o.when||'—')+' · 連絡：'+esc(o.contact||'—')+'</div>'+stepsHtml(o.status)+
        (o.comment?'<p class="ac-note">ご要望：'+esc(o.comment)+'</p>':'')+
        '<details style="margin-top:6px"><summary style="cursor:pointer;font-size:13px;font-weight:700">仕様をすべて見る</summary><pre class="ac-pre" style="margin-top:6px">'+esc(o.text)+'</pre></details>'+
        '<div class="ac-st"><select data-st="'+i+'" aria-label="状況を変更">'+STATUSES.concat(['キャンセル']).map(function(x){return '<option'+(x===o.status?' selected':'')+'>'+x+'</option>'}).join('')+'</select><button type="button" class="btn" data-act="setStatus" data-i="'+i+'" style="min-height:40px;font-size:13px">状況を更新</button><span class="ac-ok" data-stmsg="'+i+'"></span></div></div></div>'}).join('');
    }
    var boards='';
    if(r.kind==='member'){
      boards=!d.boards?'<div class="ac-empty">読み込み中…</div>':!d.boards.length?'<p class="ac-note">保存したボードはありません。</p>':
        '<div class="ac-grid" style="grid-template-columns:repeat(auto-fill,minmax(200px,1fr))">'+d.boards.map(function(b,i){return '<div class="ac-card ac-board" style="padding:12px">'+th(b.cfg)+'<div><h4>'+esc(b.name)+'</h4><div class="ac-meta">'+esc(spec(b.cfg))+'<br>'+d8(b.createdAt)+'</div><div class="ac-acts"><button type="button" class="btn ghost" data-act="viewb" data-i="'+i+'">カスタムで開く</button></div></div></div>'}).join('')+'</div>';
    }
    var hist=c.hist.slice().reverse();
    var histHtml=(hist.length?'<ul class="ac-hist">'+hist.map(function(h){return '<li><span class="d">'+esc(h.date||'—')+'</span><span><b>'+esc(h.item||'（品名なし）')+'</b>'+(h.price?'　'+esc(h.price)+'円':'')+(h.status?'　<span class="ac-kind">'+esc(h.status)+'</span>':'')+(h.note?'<br><span style="color:var(--ink-soft);font-size:12.5px">'+esc(h.note)+'</span>':'')+'</span><button type="button" class="btn danger" data-act="delHist" data-id="'+esc(h.id)+'" style="min-height:34px;padding:0 10px;font-size:12px">削除</button></li>'}).join('')+'</ul>':'<p class="ac-note">店頭・過去の注文はまだ登録されていません。</p>')+
      '<form class="ac-mini" id="acHist"><input name="date" type="date" aria-label="日付" value="'+new Date(Date.now()-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,10)+'"><input name="hitem" placeholder="品名（例：Mid 7\'2&quot; ロゴ2か所）" aria-label="品名" maxlength="120"><input name="price" inputmode="numeric" placeholder="金額（円）" aria-label="金額" maxlength="20">'+
