  function fallback(){if(fell)return;fell=true;clearTimeout(gmTimer);if(gm&&gm.parentNode)gm.parentNode.removeChild(gm);card.classList.remove('is-google');}
  try{
    gm=document.createElement('iframe');
    gm.src='https://maps.google.com/maps?q=35.0297482,139.9990191&hl=ja&z=15&output=embed';
    gm.title='Google マップ：SPLASH / RIPSTIX（千葉県南房総市和田町白渚586-2）';gm.referrerPolicy='no-referrer-when-downgrade';gm.setAttribute('allowfullscreen','');
    document.addEventListener('securitypolicyviolation',function(e){if(/google/.test(e.blockedURI||'')||e.violatedDirective&&/frame|child|default/.test(e.violatedDirective)&&!fell&&/google|^$/.test(e.blockedURI||''))fallback()});
    card.classList.add('is-google');view.appendChild(gm);
    /* a frame that never finishes loading (offline, blocked network) also falls back */
    var loaded=false;gm.addEventListener('load',function(){loaded=true});
    gmTimer=setTimeout(function(){if(!loaded)fallback()},12000);
  }catch(e){fallback()}
  var W=1536,H=1024,home={x:267,y:740,s:1.9},vb={x:0,y:0,w:W,h:H},drag=null;
  function apply(){svgm.setAttribute('viewBox',[vb.x,vb.y,vb.w,vb.h].map(function(v){return v.toFixed(1)}).join(' '))}
  /* the frame can be wider than the drawing (3:2): match the view's shape so there are no empty bands at the sides */
  function asp(){var r=view.getBoundingClientRect();return r.width>0&&r.height>0?r.height/r.width:H/W}
  function maxW(){return Math.min(W,H/asp())}
  function clampVb(){var a=asp();vb.w=clamp(vb.w,W/4.5,maxW());vb.h=vb.w*a;vb.x=clamp(vb.x,0,W-vb.w);vb.y=clamp(vb.y,0,H-vb.h)}
  function zoomAt(f,cx,cy,anim){
    var nw=clamp(vb.w/f,W/4.5,maxW()),nh=nw*asp(),tx=cx-(cx-vb.x)*nw/vb.w,ty=cy-(cy-vb.y)*nh/vb.h;
    animTo({x:tx,y:ty,w:nw},anim);
  }
  var raf=0;function animTo(t,anim){cancelAnimationFrame(raf);if(!anim||reduce){vb.x=t.x;vb.w=t.w;vb.y=t.y;clampVb();apply();return}
    var s={x:vb.x,y:vb.y,w:vb.w},t0=performance.now();(function step(now){var k=Math.min(1,(now-t0)/380),e=1-Math.pow(1-k,3);vb.x=s.x+(t.x-s.x)*e;vb.y=s.y+(t.y-s.y)*e;vb.w=s.w+(t.w-s.w)*e;clampVb();apply();if(k<1)raf=requestAnimationFrame(step)})(t0)}
  function goHome(anim){var w=Math.min(W/home.s,maxW()),h=w*asp();animTo({x:home.x-w/2,y:home.y-h/2,w:w},anim)}
  /* open on the whole area, then glide toward the shop once the map scrolls into view */
  clampVb();apply();
  window.addEventListener('resize',function(){clampVb();apply()});
  if(window.IntersectionObserver){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){io.disconnect();setTimeout(function(){goHome(true)},350)}},{threshold:.5});io.observe(view)}
  $('mpIn').addEventListener('click',function(){zoomAt(1.5,vb.x+vb.w/2,vb.y+vb.h/2,true)});
  $('mpOut').addEventListener('click',function(){zoomAt(1/1.5,vb.x+vb.w/2,vb.y+vb.h/2,true)});
  $('mpHome').addEventListener('click',function(){goHome(true)});
  function toSvg(e){var r=view.getBoundingClientRect();return {x:vb.x+(e.clientX-r.left)/r.width*vb.w,y:vb.y+(e.clientY-r.top)/r.height*vb.h}}
  var pts={};
  view.addEventListener('pointerdown',function(e){if(e.target.closest('.map-ctl'))return;view.setPointerCapture(e.pointerId);pts[e.pointerId]={x:e.clientX,y:e.clientY};
    if(Object.keys(pts).length===1){drag={x:e.clientX,y:e.clientY,vx:vb.x,vy:vb.y,moved:0};view.classList.add('dragging')}else{drag=null}});
  view.addEventListener('pointermove',function(e){
    if(!pts[e.pointerId])return;var ids=Object.keys(pts);
    if(ids.length===2){var a=pts[ids[0]],b=pts[ids[1]],d0=Math.hypot(a.x-b.x,a.y-b.y);pts[e.pointerId]={x:e.clientX,y:e.clientY};a=pts[ids[0]];b=pts[ids[1]];var d1=Math.hypot(a.x-b.x,a.y-b.y);
      if(d0>0){var m=toSvg({clientX:(a.x+b.x)/2,clientY:(a.y+b.y)/2});zoomAt(d1/d0,m.x,m.y,false)}return}
    pts[e.pointerId]={x:e.clientX,y:e.clientY};if(!drag)return;
    var r=view.getBoundingClientRect(),dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.moved=Math.max(drag.moved,Math.abs(dx)+Math.abs(dy));
    vb.x=drag.vx-dx/r.width*vb.w;vb.y=drag.vy-dy/r.height*vb.h;clampVb();apply()});
  function end(e){delete pts[e.pointerId];if(!Object.keys(pts).length){view.classList.remove('dragging');drag=null}}
  view.addEventListener('pointerup',end);view.addEventListener('pointercancel',end);
  view.addEventListener('wheel',function(e){if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();var m=toSvg(e);zoomAt(e.deltaY<0?1.15:1/1.15,m.x,m.y,false)},{passive:false});
  /* tooltips on the map's points of interest */
  var tip=document.createElement('div');tip.className='map-tip';tip.hidden=true;view.appendChild(tip);
  svgm.querySelectorAll('.mp-poi').forEach(function(g){g.style.cursor='pointer';
    function show(){var r=g.getBoundingClientRect(),vr=view.getBoundingClientRect();tip.textContent=g.getAttribute('data-tip');tip.style.left=(r.left+r.width/2-vr.left)+'px';tip.style.top=(r.top-vr.top)+'px';tip.hidden=false}
    g.addEventListener('pointerenter',show);g.addEventListener('pointerleave',function(){tip.hidden=true});g.addEventListener('click',function(){tip.hidden?show():tip.hidden=true})});
  /* copy address */
  $('acCopy').addEventListener('click',function(){var t='〒299-2711 千葉県南房総市和田町白渚586-2',done=function(){$('acCopied').textContent='住所をコピーしました。'};
    try{navigator.clipboard.writeText(t).then(done,function(){$('acCopied').textContent=t})}catch(e){$('acCopied').textContent=t}});
