/* ================= HERO WATER RIPPLE ================= */
(function(){
  var cv=$('ripple'),hero=$('hero');if(!cv||reduce)return;var ctx=cv.getContext('2d');if(!ctx)return;
  var S=4,cw=0,ch=0,a,b,img,run=false,raf=0,lastDrop=0,vis=true;
  function size(){var r=hero.getBoundingClientRect();cw=Math.max(8,Math.ceil(r.width/S));ch=Math.max(8,Math.ceil(r.height/S));cv.width=cw;cv.height=ch;a=new Float32Array(cw*ch);b=new Float32Array(cw*ch);img=ctx.createImageData(cw,ch)}
  function drop(x,y,r,f){var cx=(x/S)|0,cy=(y/S)|0;for(var j=-r;j<=r;j++)for(var i=-r;i<=r;i++){var X=cx+i,Y=cy+j;if(X<1||Y<1||X>=cw-1||Y>=ch-1)continue;var d=Math.sqrt(i*i+j*j);if(d<=r)a[Y*cw+X]+=f*(1-d/r)}}
  function step(){var n,i,x,y;for(y=1;y<ch-1;y++){for(x=1;x<cw-1;x++){i=y*cw+x;n=(a[i-1]+a[i+1]+a[i-cw]+a[i+cw])*0.5-b[i];b[i]=n*0.972}}var t=a;a=b;b=t}
  function draw(){var d=img.data,i,s,k;for(var y=1;y<ch-1;y++){for(var x=1;x<cw-1;x++){i=y*cw+x;s=(a[i-1]-a[i+1])+(a[i-cw]-a[i+cw]);k=i*4;
    if(s>0){d[k]=225;d[k+1]=245;d[k+2]=255;d[k+3]=Math.min(150,s*1.5)}else{d[k]=8;d[k+1]=30;d[k+2]=46;d[k+3]=Math.min(110,-s*1.1)}}}ctx.putImageData(img,0,0)}
  function loop(now){raf=requestAnimationFrame(loop);if(now-lastDrop>900+Math.random()*900){lastDrop=now;drop(Math.random()*cw*S,(0.35+Math.random()*0.6)*ch*S,3,140)}step();draw()}
