  function stop(){run=false;cancelAnimationFrame(raf)}
  size();
  var lx=-1,ly=-1;
  hero.addEventListener('pointermove',function(e){var r=hero.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(lx<0||Math.hypot(x-lx,y-ly)>10){drop(x,y,2,110);lx=x;ly=y}},{passive:true});
  hero.addEventListener('pointerdown',function(e){var r=hero.getBoundingClientRect();drop(e.clientX-r.left,e.clientY-r.top,4,420)},{passive:true});
  window.addEventListener('resize',function(){size()});
  if(window.IntersectionObserver)new IntersectionObserver(function(es){vis=es[0].isIntersecting;vis?start():stop()},{threshold:0}).observe(hero);
  document.addEventListener('visibilitychange',function(){document.hidden?stop():start()});
  start();
})();
var topBar=$('top');function headState(){topBar.classList.toggle('solid',window.scrollY>window.innerHeight*.6)}
window.addEventListener('scroll',headState,{passive:true});headState();
/* entry band: a fan deck of 13 color studies; each one opens the builder pre-loaded */
var FAN=[
  ['fish',{pat:'dip',deck:'#f4f3ee',accent:'#16191c',logo:'coffin'},'BLACK DIP'],
  ['short',{pat:'twotone',deck:'#16191c',accent:'#b9d65a',logo:'block',ori:'v',logoColor:'#f4f3ee'},'LIME SPLIT'],
  ['mid',{pat:'grad',deck:'#b7dbe8',accent:'#2d6f9e',logo:'script',ori:'v'},'DEEP SKY'],
  ['grov',{pat:'solid',deck:'#f1cfd9',accent:'#e0559a',logo:'label'},'BABY PINK'],
  ['long',{pat:'railfade',deck:'#d8c7a8',accent:'#4a5155',logo:'coffin'},'SAND × CHARCOAL'],
  ['fish',{pat:'railfade',deck:'#ece6f4',accent:'#b9a6dc',logo:'script',ori:'v'},'LAVENDER FADE'],
  ['mid',{pat:'solid',deck:'#f7f7f3',accent:'#16191c',logo:'coffin'},'CLEAR WHITE'],
  ['short',{pat:'grad',deck:'#f4f3ee',accent:'#2d6f9e',logo:'block',ori:'v'},'OCEAN DROP'],
  ['grov',{pat:'dip',deck:'#f4f3ee',accent:'#f08a6c',logo:'coffin'},'CORAL DIP'],
  ['long',{pat:'solid',deck:'#d0a01c',accent:'#8a6a4e',logo:'label',pin:true,pinColor:'#16191c'},'MUSTARD'],
  ['mid',{pat:'twotone',deck:'#b7dbe8',accent:'#3fbf8f',logo:'script',ori:'v'},'MINT × SKY'],
  ['short',{pat:'railfade',deck:'#efe2ea',accent:'#e0559a',logo:'script',ori:'v'},'MAGIC STICK'],
  ['fish',{pat:'railfade',deck:'#c2a585',accent:'#231c18',logo:'coffin'},'SEPIA FADE']
];
var fdStage=$('fdStage'),fdRead=$('fdRead'),fdDef=fdRead.innerHTML;
function fanCfg(x){var t=TYPE_BY[x[0]],o=x[1],c=JSON.parse(JSON.stringify(DEFAULT));
  Object.assign(c,{type:t.id,L:t.L[2],W:t.W[2],T:t.T[2],tail:t.tails[0],fin:t.fins[0],pat:o.pat,deck:o.deck,accent:o.accent,pin:!!o.pin,pinColor:o.pinColor||c.pinColor});
  c.logoD={on:true,logo:o.logo,ori:o.ori||'h',color:o.logoColor||'#16191c',pos:{u:0,t:o.ori==='v'?.42:.3}};return c}
FAN.forEach(function(x,k){
  var c=fanCfg(x),t=TYPE_BY[c.type],o=outline(t,c.tail,c.W,c.L),pad=1;
  var b=document.createElement('button');b.type='button';b.className='fd-board';
  b.style.setProperty('--i',k-(FAN.length-1)/2);b.style.setProperty('--s',(.74+.26*(c.L-62)/(116-62)).toFixed(3));b.style.setProperty('--ar',((c.W+2*pad)/(c.L+2*pad)).toFixed(4));
  b.style.zIndex=String(20-Math.abs(k-(FAN.length-1)/2)|0);
  b.setAttribute('aria-label',x[2]+'（'+t.jp+' '+ftIn(c.L)+'）でカスタムをはじめる');
  var sv=document.createElementNS(NS,'svg');sv.setAttribute('viewBox',[-c.W/2-pad,-pad,c.W+2*pad,c.L+2*pad].join(' '));sv.setAttribute('aria-hidden','true');
  drawBoard(el('g',{},sv),c,{view:'deck',pts:o.pts,P:o.P});b.appendChild(sv);
  var show=function(){fdRead.innerHTML='<b>'+x[2]+'</b>'+t.en+' · '+ftIn(c.L)+' · '+PATTERNS.filter(function(p){return p.id===c.pat})[0].jp};
  b.addEventListener('mouseenter',show);b.addEventListener('focus',show);
  b.addEventListener('mouseleave',function(){fdRead.innerHTML=fdDef});b.addEventListener('blur',function(){fdRead.innerHTML=fdDef});
  b.addEventListener('click',function(){var n=fanCfg(x);Object.keys(n).forEach(function(key){cfg[key]=n[key]});save();step=2;setView('deck');openCustom(b)});
  fdStage.insertBefore(b,fdStage.firstChild);
});

if(!window.gsap||!window.ScrollTrigger||reduce)return;
gsap.registerPlugin(ScrollTrigger);
var mobile=window.matchMedia('(max-width:860px)').matches;

/* hero: a wall of boards that drifts apart as you scroll */
var bds=gsap.utils.toArray('#wall .bd'),nB=bds.length;
bds.forEach(function(e,i){var o=i-(nB-1)/2;gsap.set(e,{rotation:o*1.6,y:Math.abs(o)*6})});
gsap.from(bds,{y:'+=160',opacity:0,duration:1.1,ease:'power3.out',stagger:{each:.07,from:'center'}});
var heroTl=gsap.timeline({scrollTrigger:{trigger:'#hero',start:'top top',end:'bottom top',scrub:.6}});
bds.forEach(function(e,i){var o=i-(nB-1)/2;heroTl.to(e,{x:o*(mobile?4:3.2)+'vw',y:-(60+((i*37)%5)*34),rotation:o*4.5,duration:1,ease:'none'},0)});
heroTl.to('.hero-word',{scale:1.2,opacity:.35,duration:1,ease:'none'},0).to('.hero-copy',{y:-30,opacity:0,duration:.4},0);

/* fan deck opens like a swatch book as the band scrolls in */
gsap.fromTo('#fanDeck',{'--open':0.08},{'--open':1,ease:'none',scrollTrigger:{trigger:'#build',start:'top 85%',end:'top 15%',scrub:.6}});
gsap.from('#build h2 span',{y:60,opacity:0,stagger:.12,duration:.8,ease:'power3.out',scrollTrigger:{trigger:'#build',start:'top 70%'}});

/* statement */
gsap.fromTo('#stBoard',{rotation:-12,yPercent:-30,y:'30vh'},{rotation:90,yPercent:-50,y:0,ease:'none',
  scrollTrigger:{trigger:'#statement',start:'top top',end:'+=120%',scrub:.6,pin:true,onEnter:function(){setTint('#0d2230')}}});
gsap.from('.st-word',{scale:.8,opacity:.3,ease:'none',scrollTrigger:{trigger:'#statement',start:'top 80%',end:'top top',scrub:true}});

/* rack tint */
ScrollTrigger.create({trigger:'#lineup',start:'top 60%',end:'bottom 40%',
  onEnter:function(){lineupActive=true;setTint(BOARDS[current].tint)},onEnterBack:function(){lineupActive=true;setTint(BOARDS[current].tint)},
  onLeave:function(){lineupActive=false;setTint('#0d2230')},onLeaveBack:function(){lineupActive=false;setTint('#0d2230')}});
gsap.from('#rack button',{y:80,opacity:0,stagger:.08,duration:.8,ease:'power3.out',scrollTrigger:{trigger:'#rack',start:'top 85%'}});
})();
</script>

</body>
